/**
 * ChatGPT Navigator - 目录导航 & Markdown 导出
 * 在 chatgpt.com 会话页面左侧注入浮动导航面板
 */

(function () {
  'use strict';

  // ========== 选择器配置 ==========
  // ChatGPT 页面 DOM 选择器（如页面结构变化，只需改这里）
  const SEL = {
    // 会话消息容器（role=presentation 的主滚动区域）
    conversationContainer: '[role="presentation"]',
    // 单条消息: data-message-author-role 标注角色
    userMessage: '[data-message-author-role="user"]',
    assistantMessage: '[data-message-author-role="assistant"]',
    // 所有消息
    allMessages: '[data-message-author-role]',
    // 消息内部的 markdown 渲染区域
    markdownBody: '.markdown',
  };

  let panel = null;
  let navList = null;
  let observer = null;
  let urlCheckInterval = null;
  let lastUrl = '';

  // ========== 初始化面板 ==========
  function createPanel() {
    if (document.getElementById('cgpt-nav-panel')) return;

    panel = document.createElement('div');
    panel.id = 'cgpt-nav-panel';
    panel.innerHTML = `
      <div id="cgpt-nav-header">
        <span>📑 会话导航</span>
      </div>
      <button id="cgpt-nav-toggle" title="收起/展开">◀</button>
      <div id="cgpt-nav-list"></div>
      <div id="cgpt-nav-footer">
        <button id="cgpt-nav-export-btn">📥 导出为 Markdown</button>
      </div>
    `;
    document.body.appendChild(panel);

    navList = document.getElementById('cgpt-nav-list');

    // 折叠/展开
    document.getElementById('cgpt-nav-toggle').addEventListener('click', () => {
      const isCollapsed = panel.classList.toggle('collapsed');
      document.getElementById('cgpt-nav-toggle').textContent = isCollapsed ? '▶' : '◀';
    });

    // 导出按钮
    document.getElementById('cgpt-nav-export-btn').addEventListener('click', exportMarkdown);

    // 首次构建导航
    refreshNav();
  }

  function removePanel() {
    if (panel) {
      panel.remove();
      panel = null;
      navList = null;
    }
  }

  // ========== 判断是否为会话页面 ==========
  function isConversationPage() {
    const path = location.pathname;
    // /c/xxx 或 /share/xxx 或 /g/xxx 等会话路径
    return /^\/(c|share|g)\/[a-zA-Z0-9-]+/.test(path) || /^\/[a-f0-9-]{36}/.test(path);
  }

  // ========== 构建导航目录 ==========
  function refreshNav() {
    if (!navList) return;

    const items = extractNavItems();

    if (items.length === 0) {
      navList.innerHTML = '<div id="cgpt-nav-empty">暂无会话内容</div>';
      return;
    }

    navList.innerHTML = '';
    items.forEach((item) => {
      const el = document.createElement('div');
      el.className = 'cgpt-nav-item';
      el.dataset.type = item.type;
      if (item.level) el.dataset.level = item.level;
      el.textContent = item.text;
      el.title = item.text;
      el.addEventListener('click', () => {
        item.element.scrollIntoView({ behavior: 'smooth', block: 'start' });
        // 高亮当前
        navList.querySelectorAll('.cgpt-nav-item').forEach((n) => n.classList.remove('active'));
        el.classList.add('active');
      });
      navList.appendChild(el);
    });
  }

  function extractNavItems() {
    const items = [];
    const messages = document.querySelectorAll(SEL.allMessages);

    messages.forEach((msg) => {
      const role = msg.getAttribute('data-message-author-role');

      if (role === 'user') {
        // 用户消息：提取文本作为导航节点
        const text = getMessageText(msg);
        if (text.trim()) {
          items.push({
            type: 'user',
            text: truncate(text.trim(), 60),
            element: msg,
          });
        }
      } else if (role === 'assistant') {
        // 助手消息：提取其中的 h1-h6 标题
        const mdBody = msg.querySelector(SEL.markdownBody) || msg;
        const headings = mdBody.querySelectorAll('h1, h2, h3, h4, h5, h6');
        headings.forEach((h) => {
          const level = parseInt(h.tagName[1], 10);
          const text = h.textContent.trim();
          if (text) {
            items.push({
              type: 'heading',
              level,
              text: truncate(text, 60),
              element: h,
            });
          }
        });
      }
    });

    return items;
  }

  function getMessageText(msgEl) {
    // 尝试多种方式获取用户消息文本
    const whiteboard = msgEl.querySelector('[data-message-author-role="user"] .whitespace-pre-wrap');
    if (whiteboard) return whiteboard.textContent;

    const innerDiv = msgEl.querySelector('.whitespace-pre-wrap');
    if (innerDiv) return innerDiv.textContent;

    // fallback: 直接取所有文本
    return msgEl.textContent;
  }

  function truncate(text, maxLen) {
    // 合并换行和多余空白
    const clean = text.replace(/\s+/g, ' ');
    return clean.length > maxLen ? clean.slice(0, maxLen) + '…' : clean;
  }

  // ========== Markdown 导出 ==========
  function exportMarkdown() {
    const messages = document.querySelectorAll(SEL.allMessages);
    const parts = [];

    messages.forEach((msg) => {
      const role = msg.getAttribute('data-message-author-role');

      if (role === 'user') {
        const text = getMessageText(msg).trim();
        if (text) {
          parts.push(`## 🧑 User\n\n${text}`);
        }
      } else if (role === 'assistant') {
        const mdBody = msg.querySelector(SEL.markdownBody) || msg;
        const md = htmlToMarkdown(mdBody);
        if (md.trim()) {
          parts.push(`## 🤖 Assistant\n\n${md.trim()}`);
        }
      }
    });

    if (parts.length === 0) {
      alert('未检测到会话内容');
      return;
    }

    // 获取会话标题
    const titleEl = document.querySelector('title');
    const title = titleEl ? titleEl.textContent.replace(/ \| ChatGPT$/, '').trim() : 'ChatGPT 会话';

    const markdown = `# ${title}\n\n${parts.join('\n\n---\n\n')}\n`;
    downloadFile(`${title}.md`, markdown);
  }

  // ========== HTML → Markdown 转换 ==========
  function htmlToMarkdown(root) {
    return convertNode(root).trim();
  }

  function convertNode(node) {
    if (node.nodeType === Node.TEXT_NODE) {
      return node.textContent;
    }

    if (node.nodeType !== Node.ELEMENT_NODE) return '';

    const tag = node.tagName.toLowerCase();

    // 跳过按钮等非内容元素
    if (['button', 'svg', 'nav', 'style', 'script'].includes(tag)) return '';

    const children = () => convertChildren(node);

    switch (tag) {
      // 标题
      case 'h1': return `\n\n# ${children()}\n\n`;
      case 'h2': return `\n\n## ${children()}\n\n`;
      case 'h3': return `\n\n### ${children()}\n\n`;
      case 'h4': return `\n\n#### ${children()}\n\n`;
      case 'h5': return `\n\n##### ${children()}\n\n`;
      case 'h6': return `\n\n###### ${children()}\n\n`;

      // 段落和换行
      case 'p': return `\n\n${children()}\n\n`;
      case 'br': return '\n';
      case 'hr': return '\n\n---\n\n';

      // 行内格式
      case 'strong':
      case 'b':
        return `**${children()}**`;
      case 'em':
      case 'i':
        return `*${children()}*`;
      case 'del':
      case 's':
        return `~~${children()}~~`;
      case 'code': {
        // 行内 code（非 pre 下的）
        if (node.parentElement && node.parentElement.tagName.toLowerCase() === 'pre') {
          return children();
        }
        return `\`${node.textContent}\``;
      }
      case 'a': {
        const href = node.getAttribute('href') || '';
        return `[${children()}](${href})`;
      }
      case 'img': {
        const alt = node.getAttribute('alt') || '';
        const src = node.getAttribute('src') || '';
        return `![${alt}](${src})`;
      }

      // 代码块
      case 'pre': {
        const codeEl = node.querySelector('code');
        const code = codeEl ? codeEl.textContent : node.textContent;
        // 尝试提取语言（ChatGPT 常在 class 中标注 language-xxx）
        let lang = '';
        if (codeEl) {
          const cls = codeEl.className || '';
          const m = cls.match(/language-(\S+)/);
          if (m) lang = m[1];
        }
        // 也尝试从代码块上方的语言标签提取
        if (!lang) {
          const header = node.parentElement?.querySelector('span, div');
          if (header && header.textContent.length < 30) {
            lang = header.textContent.trim().toLowerCase();
          }
        }
        return `\n\n\`\`\`${lang}\n${code.replace(/\n$/, '')}\n\`\`\`\n\n`;
      }

      // 列表
      case 'ul': return `\n\n${convertList(node, 'ul')}\n\n`;
      case 'ol': return `\n\n${convertList(node, 'ol')}\n\n`;
      case 'li': return children(); // handled by convertList

      // 表格
      case 'table': return `\n\n${convertTable(node)}\n\n`;

      // 引用
      case 'blockquote': {
        const content = children().trim();
        return `\n\n${content.split('\n').map((l) => `> ${l}`).join('\n')}\n\n`;
      }

      // div、span 等容器直接递归
      default:
        return children();
    }
  }

  function convertChildren(node) {
    let result = '';
    for (const child of node.childNodes) {
      result += convertNode(child);
    }
    return result;
  }

  function convertList(ul, type) {
    const items = [];
    let index = 1;
    for (const li of ul.children) {
      if (li.tagName.toLowerCase() !== 'li') continue;
      const prefix = type === 'ol' ? `${index}. ` : '- ';
      const content = convertChildren(li).trim().replace(/\n/g, '\n  ');
      items.push(`${prefix}${content}`);
      index++;
    }
    return items.join('\n');
  }

  function convertTable(table) {
    const rows = [];
    table.querySelectorAll('tr').forEach((tr) => {
      const cells = [];
      tr.querySelectorAll('th, td').forEach((cell) => {
        cells.push(convertChildren(cell).trim().replace(/\|/g, '\\|'));
      });
      rows.push(`| ${cells.join(' | ')} |`);
    });
    if (rows.length > 0) {
      // 在第一行后插入分隔行
      const colCount = (rows[0].match(/\|/g) || []).length - 1;
      const separator = `| ${Array(colCount).fill('---').join(' | ')} |`;
      rows.splice(1, 0, separator);
    }
    return rows.join('\n');
  }

  // ========== 文件下载 ==========
  function downloadFile(filename, content) {
    const blob = new Blob([content], { type: 'text/markdown;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  // ========== DOM 变化监听 ==========
  function startObserver() {
    if (observer) observer.disconnect();

    // 防抖刷新
    let debounceTimer = null;
    const debouncedRefresh = () => {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(refreshNav, 500);
    };

    observer = new MutationObserver((mutations) => {
      // 只在有实质 DOM 变化时刷新（添加/移除节点，或文本变化）
      for (const m of mutations) {
        if (m.addedNodes.length > 0 || m.removedNodes.length > 0) {
          debouncedRefresh();
          return;
        }
      }
    });

    // 监听 body 下所有子树变化
    observer.observe(document.body, {
      childList: true,
      subtree: true,
    });
  }

  // ========== URL 变化检测（SPA 路由） ==========
  function startUrlWatcher() {
    lastUrl = location.href;
    urlCheckInterval = setInterval(() => {
      if (location.href !== lastUrl) {
        lastUrl = location.href;
        onUrlChange();
      }
    }, 1000);
  }

  function onUrlChange() {
    if (isConversationPage()) {
      createPanel();
      // 延迟刷新以等待页面渲染
      setTimeout(refreshNav, 1500);
    } else {
      removePanel();
    }
  }

  // ========== 入口 ==========
  function init() {
    if (isConversationPage()) {
      createPanel();
    }
    startObserver();
    startUrlWatcher();
  }

  // 等待页面加载
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

