/**
 * 使用 Puppeteer 加载扩展并在 ChatGPT 分享页面验证功能
 */
import puppeteer from 'puppeteer';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const EXTENSION_PATH = __dirname; // 插件目录就是当前目录
const TEST_URL = 'https://chatgpt.com/share/69d20f2c-5898-8327-8113-9b152b15f133';

async function test() {
  console.log('=== ChatGPT Navigator 插件验证 ===\n');

  // 1. 启动带扩展的 Chrome
  console.log('1. 启动 Chrome（加载扩展）...');
  const browser = await puppeteer.launch({
    headless: false, // 扩展不支持 headless
    args: [
      `--disable-extensions-except=${EXTENSION_PATH}`,
      `--load-extension=${EXTENSION_PATH}`,
      '--no-first-run',
      '--disable-default-apps',
    ],
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900 });

  // 2. 导航到测试页面
  console.log(`2. 导航到 ${TEST_URL} ...`);
  await page.goto(TEST_URL, { waitUntil: 'networkidle2', timeout: 30000 });

  // 等待页面 JS 渲染完成
  console.log('3. 等待页面渲染...');
  await page.waitForFunction(() => document.readyState === 'complete', { timeout: 15000 });
  await new Promise((r) => setTimeout(r, 5000)); // 额外等待 SPA 渲染

  // 3. 检查 DOM 选择器
  console.log('\n--- DOM 选择器验证 ---');

  const selectors = {
    'data-message-author-role (所有消息)': '[data-message-author-role]',
    'data-message-author-role="user"': '[data-message-author-role="user"]',
    'data-message-author-role="assistant"': '[data-message-author-role="assistant"]',
    '.markdown (渲染区域)': '.markdown',
    '.whitespace-pre-wrap (用户文本)': '.whitespace-pre-wrap',
    'role="presentation"': '[role="presentation"]',
    'article 标签': 'article',
    '[data-testid*="conversation"]': '[data-testid*="conversation"]',
  };

  for (const [name, sel] of Object.entries(selectors)) {
    const count = await page.$$eval(sel, (els) => els.length).catch(() => 0);
    console.log(`  ${count > 0 ? '✅' : '❌'} ${name}: ${count} 个元素`);
  }

  // 探测可能的替代选择器
  console.log('\n--- 探测页面结构 ---');

  // 查找所有带 data- 属性的元素
