const CHROME_PATH = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';

async function test() {
  console.log('=== ChatGPT Navigator 插件验证 ===\n');

  // 1. 启动带扩展的 Chrome
  console.log('1. 启动 Chrome（加载扩展）...');
  const browser = await puppeteer.launch({
    headless: false, // 扩展不支持 headless
    executablePath: CHROME_PATH,
    args: [
      `--disable-extensions-except=${EXTENSION_PATH}`,
      `--load-extension=${EXTENSION_PATH}`,
      '--no-first-run',
      '--disable-default-apps',
    ],
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900 });

  // 2. 导航到测试页面
  console.log(`2. 导航到 ${TEST_URL} ...`);
  await page.goto(TEST_URL, { waitUntil: 'networkidle2', timeout: 30000 });

  // 等待页面 JS 渲染完成
  console.log('3. 等待页面渲染...');
  await page.waitForFunction(() => document.readyState === 'complete', { timeout: 15000 });
  await new Promise((r) => setTimeout(r, 5000)); // 额外等待 SPA 渲染

  // 3. 检查 DOM 选择器
  console.log('\n--- DOM 选择器验证 ---');

  const selectors = {
    'data-message-author-role (所有消息)': '[data-message-author-role]',
    'data-message-author-role="user"': '[data-message-author-role="user"]',
    'data-message-author-role="assistant"': '[data-message-author-role="assistant"]',
    '.markdown (渲染区域)': '.markdown',
    '.whitespace-pre-wrap (用户文本)': '.whitespace-pre-wrap',
    'role="presentation"': '[role="presentation"]',
    'article 标签': 'article',
    '[data-testid*="conversation"]': '[data-testid*="conversation"]',
  };

  for (const [name, sel] of Object.entries(selectors)) {
    const count = await page.$$eval(sel, (els) => els.length).catch(() => 0);
    console.log(`  ${count > 0 ? '✅' : '❌'} ${name}: ${count} 个元素`);
  }

  // 探测可能的替代选择器
  console.log('\n--- 探测页面结构 ---');

  // 查找所有带 data- 属性的元素
  const dataAttrs = await page.evaluate(() => {
    const attrs = new Set();
    document.querySelectorAll('*').forEach((el) => {
      for (const attr of el.attributes) {
        if (attr.name.startsWith('data-') && attr.name.includes('message')) {
          attrs.add(`${attr.name}="${attr.value}" (tag: ${el.tagName.toLowerCase()})`);
        }
      }
    });
    return [...attrs].slice(0, 30);
  });
  console.log('  带 message 的 data 属性:');
  dataAttrs.forEach((a) => console.log(`    - ${a}`));

  if (dataAttrs.length === 0) {
    // 退一步：查找所有 data- 属性
    const allDataAttrs = await page.evaluate(() => {
      const attrMap = {};
      document.querySelectorAll('*').forEach((el) => {
        for (const attr of el.attributes) {
          if (attr.name.startsWith('data-')) {
            attrMap[attr.name] = (attrMap[attr.name] || 0) + 1;
          }
        }
      });
      return Object.entries(attrMap)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 20);
    });
    console.log('  所有 data- 属性（按数量排序）:');
    allDataAttrs.forEach(([name, count]) => console.log(`    - ${name}: ${count} 个`));
  }

  // 查找会话内容区域的 class 结构
  const mainStructure = await page.evaluate(() => {
    const main = document.querySelector('main') || document.querySelector('#main');
    if (!main) return '未找到 main 元素';
    const walk = (el, depth = 0) => {
      if (depth > 4) return '';
      const cls = el.className && typeof el.className === 'string' ? `.${el.className.split(' ').join('.')}` : '';
      const id = el.id ? `#${el.id}` : '';
      const role = el.getAttribute('role') ? `[role="${el.getAttribute('role')}"]` : '';
      const tag = el.tagName.toLowerCase();
      let result = `${'  '.repeat(depth)}${tag}${id}${cls}${role} (children: ${el.children.length})\n`;
      if (depth < 3) {
        for (const child of el.children) {
          result += walk(child, depth + 1);
        }
      }
      return result;
    };
    return walk(main);
  });
  console.log('\n  main 元素结构:');
  console.log(mainStructure);

  // 4. 检查插件面板
  console.log('\n--- 插件面板验证 ---');
  const panelExists = await page.$('#cgpt-nav-panel');
