  if (panelExists) {
    const navItems = await page.$$eval('.cgpt-nav-item', (items) =>
      items.map((i) => ({ type: i.dataset.type, text: i.textContent.slice(0, 50) }))
    );
    console.log(`  导航条目数量: ${navItems.length}`);
    navItems.slice(0, 10).forEach((item, i) =>
      console.log(`    [${i}] ${item.type}: ${item.text}`)
    );

    // 5. 测试点击滚动
    if (navItems.length > 1) {
      console.log('\n  测试点击第2个导航条目...');
      const scrollBefore = await page.evaluate(() => window.scrollY);
      await page.click('.cgpt-nav-item:nth-child(2)');
      await new Promise((r) => setTimeout(r, 1500));
      const scrollAfter = await page.evaluate(() => window.scrollY);
      console.log(`  ${scrollBefore !== scrollAfter ? '✅' : '⚠️'} 滚动: ${scrollBefore} → ${scrollAfter}`);
    }

    // 6. 测试导出
    console.log('\n  测试导出按钮...');
    // 监听下载
    const client = await page.createCDPSession();
    await client.send('Page.setDownloadBehavior', {
      behavior: 'allow',
      downloadPath: path.join(__dirname, 'test-downloads'),
    });
    await page.click('#cgpt-nav-export-btn');
    await new Promise((r) => setTimeout(r, 2000));
    console.log('  ✅ 导出按钮已点击（检查 test-downloads 目录）');
  }

  // 截图
  const screenshotPath = path.join(__dirname, 'test-screenshot.png');
  await page.screenshot({ path: screenshotPath, fullPage: false });
  console.log(`\n截图已保存: ${screenshotPath}`);

  console.log('\n=== 验证完成 ===');
  await browser.close();
}

test().catch((err) => {
