/**
 * 使用 Puppeteer 加载扩展并在 ChatGPT 分享页面验证功能
 */
import { createRequire } from 'module';
import path from 'path';
import { fileURLToPath } from 'url';

const require = createRequire('/Users/leon/Library/pnpm/global/5/node_modules/puppeteer/');
const puppeteer = require('puppeteer');

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const EXTENSION_PATH = __dirname;
const TEST_URL = 'https://chatgpt.com/share/69d20f2c-5898-8327-8113-9b152b15f133';
const CHROME_PATH = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';

async function test() {
  console.log('=== ChatGPT Navigator 插件验证 ===\n');

  // 1. 启动带扩展的 Chrome
  console.log('1. 启动 Chrome（加载扩展）...');
  const browser = await puppeteer.launch({
    headless: false,
    executablePath: CHROME_PATH,
    args: [
      `--disable-extensions-except=${EXTENSION_PATH}`,
      `--load-extension=${EXTENSION_PATH}`,
      '--no-first-run',
      '--disable-default-apps',
    ],
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900 });

  // 2. 导航到测试页面
  console.log(`2. 导航到测试页面...`);
  await page.goto(TEST_URL, { waitUntil: 'domcontentloaded', timeout: 60000 });

  // 等待页面 JS 渲染完成
  console.log('3. 等待页面渲染...');
  await page.waitForFunction(() => document.readyState === 'complete', { timeout: 15000 });
  await new Promise((r) => setTimeout(r, 5000));

  // 3. 检查 DOM 选择器
  console.log('\n--- DOM 选择器验证 ---');

  const selectors = {
    'data-message-author-role (所有)': '[data-message-author-role]',
    'role="user"': '[data-message-author-role="user"]',
    'role="assistant"': '[data-message-author-role="assistant"]',
    '.markdown': '.markdown',
    '.whitespace-pre-wrap': '.whitespace-pre-wrap',
    'role="presentation"': '[role="presentation"]',
    'article': 'article',
  };

  for (const [name, sel] of Object.entries(selectors)) {
    const count = await page.$$eval(sel, (els) => els.length).catch(() => 0);
    console.log(`  ${count > 0 ? '✅' : '❌'} ${name}: ${count} 个`);
  }

  // 探测页面结构
  console.log('\n--- 探测页面 data-* 属性 ---');
  const dataAttrs = await page.evaluate(() => {
    const attrMap = {};
    document.querySelectorAll('*').forEach((el) => {
      for (const attr of el.attributes) {
        if (attr.name.startsWith('data-')) {
          attrMap[attr.name] = (attrMap[attr.name] || 0) + 1;
        }
      }
    });
    return Object.entries(attrMap).sort((a, b) => b[1] - a[1]).slice(0, 25);
  });
  dataAttrs.forEach(([name, count]) => console.log(`  ${name}: ${count}`));

  // 探测 main 结构
  console.log('\n--- main 结构 ---');
  const structure = await page.evaluate(() => {
    const main = document.querySelector('main');
    if (!main) return '无 main 元素';
    const walk = (el, depth = 0) => {
      if (depth > 5 || !el || !el.tagName) return '';
      const tag = el.tagName.toLowerCase();
      const cls = el.className && typeof el.className === 'string' ? el.className.split(' ').filter(c => c).slice(0, 3).map(c => '.' + c).join('') : '';
      const id = el.id ? '#' + el.id : '';
      const role = el.getAttribute('role') ? `[role=${el.getAttribute('role')}]` : '';
      const dataRole = el.getAttribute('data-message-author-role') ? `[author=${el.getAttribute('data-message-author-role')}]` : '';
      let line = '  '.repeat(depth) + tag + id + cls + role + dataRole + ` (${el.children.length}ch)\n`;
      if (el.children.length <= 20 && depth < 5) {
        for (const c of el.children) line += walk(c, depth + 1);
      }
      return line;
    };
    return walk(main);
  });
  console.log(structure.slice(0, 3000));

  // 查看 h1-h6
  console.log('\n--- 页面中的标题元素 ---');
  const headings = await page.evaluate(() => {
    const hs = document.querySelectorAll('h1, h2, h3, h4, h5, h6');
    return [...hs].slice(0, 20).map(h => `${h.tagName}: "${h.textContent.trim().slice(0, 60)}"`);
  });
  headings.forEach(h => console.log(`  ${h}`));

  // 4. 检查插件面板
  console.log('\n--- 插件面板验证 ---');
  const panelExists = await page.$('#cgpt-nav-panel');
  console.log(`  ${panelExists ? '✅' : '❌'} #cgpt-nav-panel 面板: ${!!panelExists}`);

  if (panelExists) {
    const panelVisible = await page.$eval('#cgpt-nav-panel', (el) => {
      const style = window.getComputedStyle(el);
      return { display: style.display, visibility: style.visibility, opacity: style.opacity, width: el.offsetWidth, height: el.offsetHeight };
    });
    console.log(`  面板样式: ${JSON.stringify(panelVisible)}`);

    const navItems = await page.$$eval('.cgpt-nav-item', (items) =>
      items.map((i) => ({ type: i.dataset.type, level: i.dataset.level, text: i.textContent.slice(0, 60) }))
    );
    console.log(`  导航条目: ${navItems.length} 个`);
    navItems.slice(0, 15).forEach((item, i) =>
      console.log(`    [${i}] ${item.type}${item.level ? '(h' + item.level + ')' : ''}: ${item.text}`)
    );

    if (navItems.length > 1) {
      console.log('\n  测试点击导航...');
      // 找到滚动容器
      const scrollBefore = await page.evaluate(() => {
        const container = document.querySelector('[role="presentation"]') || document.scrollingElement;
        return container.scrollTop;
      });
      await page.click('.cgpt-nav-item:nth-child(2)');
      await new Promise((r) => setTimeout(r, 1500));
      const scrollAfter = await page.evaluate(() => {
        const container = document.querySelector('[role="presentation"]') || document.scrollingElement;
        return container.scrollTop;
      });
      console.log(`  ${scrollBefore !== scrollAfter ? '✅' : '⚠️'} 滚动: ${scrollBefore} → ${scrollAfter}`);
    }

    // 测试导出
    console.log('\n  测试导出...');
    const client = await page.createCDPSession();
    const downloadDir = path.join(__dirname, 'test-downloads');
    await client.send('Page.setDownloadBehavior', { behavior: 'allow', downloadPath: downloadDir });
    await page.click('#cgpt-nav-export-btn');
    await new Promise((r) => setTimeout(r, 2000));
    console.log('  ✅ 导出按钮已点击');
  } else {
    console.log('  面板未创建，检查 isConversationPage 逻辑...');
    const urlInfo = await page.evaluate(() => ({ href: location.href, pathname: location.pathname }));
    console.log(`  URL: ${JSON.stringify(urlInfo)}`);
  }

  // 截图
  const screenshotPath = path.join(__dirname, 'test-screenshot.png');
  await page.screenshot({ path: screenshotPath, fullPage: false });
  console.log(`\n截图: ${screenshotPath}`);

  console.log('\n=== 验证完成 ===');
  await browser.close();
}

test().catch((err) => {
  console.error('测试失败:', err.message);
  process.exit(1);
});

