/**
 * 使用 Puppeteer 加载扩展并验证功能
 * 通过请求拦截将 chatgpt.com/share/xxx 映射到本地测试页面
 * 这样 content_scripts 的 matches 和 isConversationPage 都能正常工作
 */
import { createRequire } from 'module';
import path from 'path';
import fs from 'fs';
import { fileURLToPath } from 'url';

const require = createRequire('/Users/leon/Library/pnpm/global/5/node_modules/puppeteer/');
const puppeteer = require('puppeteer');

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const EXTENSION_PATH = __dirname;
const CHROME_PATH = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const TEST_HTML = fs.readFileSync(path.join(__dirname, 'test-page.html'), 'utf-8');
const FAKE_URL = 'https://chatgpt.com/share/test-conversation-123';

async function test() {
  console.log('=== ChatGPT Navigator 插件验证 ===\n');

  const browser = await puppeteer.launch({
    headless: false,
    executablePath: CHROME_PATH,
    args: [
      `--disable-extensions-except=${EXTENSION_PATH}`,
      `--load-extension=${EXTENSION_PATH}`,
      '--no-first-run',
      '--disable-default-apps',
    ],
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900 });

  // 拦截请求，把 chatgpt.com 的响应替换为本地 HTML
  await page.setRequestInterception(true);
  page.on('request', (req) => {
    if (req.url() === FAKE_URL) {
      req.respond({
        status: 200,
        contentType: 'text/html; charset=utf-8',
        body: TEST_HTML,
      });
    } else {
      req.continue();
    }
  });

  // 收集 console 日志
  const logs = [];
  page.on('console', (msg) => logs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => logs.push(`[ERROR] ${err.message}`));

  // 导航到伪造的 chatgpt.com/share URL → 触发 content_scripts 注入
  console.log(`1. 导航到 ${FAKE_URL}`);
  await page.goto(FAKE_URL, { waitUntil: 'load' });
  console.log('   等待扩展注入...');
  await new Promise((r) => setTimeout(r, 3000));

  // === 验证 DOM 选择器 ===
  console.log('\n--- DOM 选择器 ---');
  const selectorResults = {};
  for (const [name, sel] of Object.entries({
    '所有消息': '[data-message-author-role]',
    '用户消息': '[data-message-author-role="user"]',
    '助手消息': '[data-message-author-role="assistant"]',
    'markdown 区域': '.markdown',
    '用户文本': '.whitespace-pre-wrap',
    '标题 (h1-h6)': '.markdown h1, .markdown h2, .markdown h3, .markdown h4, .markdown h5, .markdown h6',
  })) {
    const count = await page.$$eval(sel, (els) => els.length).catch(() => 0);
    selectorResults[name] = count;
    console.log(`  ${count > 0 ? '✅' : '❌'} ${name}: ${count}`);
  }

  // === 验证面板 ===
  console.log('\n--- 导航面板 ---');
