    logs.forEach((l) => console.log(`  ${l}`));
  }

  // === 汇总 ===
  console.log('\n=== 验证完成 ===');
  await browser.close();
}

test().catch((err) => {
  console.error('测试失败:', err.message);
  process.exit(1);
});

