/**
 * 使用 Puppeteer 加载扩展并验证功能
 * 步骤1: 用本地模拟页面验证插件逻辑
 * 步骤2: 用 ChatGPT 分享页面验证真实场景
 */
import { createRequire } from 'module';
import path from 'path';
import fs from 'fs';
import { fileURLToPath } from 'url';

const require = createRequire('/Users/leon/Library/pnpm/global/5/node_modules/puppeteer/');
const puppeteer = require('puppeteer');

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const EXTENSION_PATH = __dirname;
const CHROME_PATH = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const LOCAL_PAGE = `file://${path.join(__dirname, 'test-page.html')}`;
const LIVE_URL = 'https://chatgpt.com/share/69d20f2c-5898-8327-8113-9b152b15f133';

async function test() {
  console.log('=== ChatGPT Navigator 插件验证 ===\n');

  const browser = await puppeteer.launch({
    headless: false,
    executablePath: CHROME_PATH,
    args: [
      `--disable-extensions-except=${EXTENSION_PATH}`,
      `--load-extension=${EXTENSION_PATH}`,
      '--no-first-run',
      '--disable-default-apps',
      '--allow-file-access-from-files',
    ],
  });

  // ==================== 测试1: 本地模拟页面 ====================
  console.log('========== 测试1: 本地模拟页面 ==========\n');

  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900 });

  // 注入 content script（file:// 页面不会自动注入 content_scripts）
  await page.goto(LOCAL_PAGE, { waitUntil: 'load' });
  await page.addStyleTag({ path: path.join(__dirname, 'styles.css') });
  await page.addScriptTag({ path: path.join(__dirname, 'content.js') });
  await new Promise((r) => setTimeout(r, 2000));

  // 检查DOM选择器
  console.log('--- DOM 选择器 ---');
  for (const [name, sel] of Object.entries({
    'data-message-author-role (所有)': '[data-message-author-role]',
    'role="user"': '[data-message-author-role="user"]',
    'role="assistant"': '[data-message-author-role="assistant"]',
    '.markdown': '.markdown',
    '.whitespace-pre-wrap': '.whitespace-pre-wrap',
    'h1-h6 in .markdown': '.markdown h1, .markdown h2, .markdown h3, .markdown h4, .markdown h5, .markdown h6',
  })) {
    const count = await page.$$eval(sel, (els) => els.length).catch(() => 0);
    console.log(`  ${count > 0 ? '✅' : '❌'} ${name}: ${count}`);
  }

  // 检查面板
  console.log('\n--- 面板检查 ---');
  const panelExists = await page.$('#cgpt-nav-panel');
  console.log(`  ${panelExists ? '✅' : '❌'} #cgpt-nav-panel 存在: ${!!panelExists}`);

  if (!panelExists) {
    // 手动检查 isConversationPage
    const urlInfo = await page.evaluate(() => ({
      href: location.href,
      pathname: location.pathname,
      isConv: /^\/(c|share|g)\/[a-zA-Z0-9-]+/.test(location.pathname) || /^\/[a-f0-9-]{36}/.test(location.pathname),
    }));
    console.log(`  URL 信息: ${JSON.stringify(urlInfo)}`);
    console.log('  ⚠️ 本地页面 pathname 不匹配会话路径，这是预期的 — isConversationPage 检查失败');
    console.log('  → 需要修改 content.js 让它在非会话 URL 也能激活（或者使面板在本地总是显示）');

    // 手动创建面板测试
    console.log('\n  手动调用 createPanel ...');
    await page.evaluate(() => {
      // 直接触发面板创建，绕过 URL 检查
      // 找到 init 之后的全局变量
    });
  }

  // 由于 content.js 是 IIFE，无法从外部调用。需要修改 content.js 让本地测试也能工作。
  // 检查 console 日志
  const consoleLogs = [];
  page.on('console', (msg) => consoleLogs.push(msg.text()));

  // 截图本地页面
  const ss1 = path.join(__dirname, 'test-screenshot-local.png');
  await page.screenshot({ path: ss1, fullPage: false });
  console.log(`\n  截图: ${ss1}`);

  // ==================== 测试2: ChatGPT 分享页面 ====================
  console.log('\n========== 测试2: ChatGPT 分享页面 ==========\n');

  const page2 = await browser.newPage();
  await page2.setViewport({ width: 1400, height: 900 });

  console.log('  导航到分享页面...');
  await page2.goto(LIVE_URL, { waitUntil: 'domcontentloaded', timeout: 60000 });

  // 多次等待并检查内容是否加载
  for (let attempt = 1; attempt <= 4; attempt++) {
    console.log(`  等待内容加载 (${attempt}/4, ${attempt * 5}s)...`);
    await new Promise((r) => setTimeout(r, 5000));

    const msgCount = await page2.$$eval('[data-message-author-role]', (els) => els.length).catch(() => 0);
    const articleCount = await page2.$$eval('article', (els) => els.length).catch(() => 0);
    console.log(`    data-message-author-role: ${msgCount}, article: ${articleCount}`);

    if (msgCount > 0 || articleCount > 0) break;
  }

  // 完整探测
  console.log('\n--- 分享页面 DOM 探测 ---');

  // 深度探测所有可能的消息容器
  const probe = await page2.evaluate(() => {
    const result = {};

    // 检查常见选择器
    const checks = [
      '[data-message-author-role]',
      '[data-message-id]',
      'article',
      '.markdown',
      '.prose',
      '.whitespace-pre-wrap',
      '[class*="message"]',
      '[class*="Message"]',
      '[class*="chat"]',
      '[class*="Chat"]',
      '[class*="turn"]',
      '[class*="Turn"]',
      '[class*="thread"]',
      '[class*="Thread"]',
      '[role="presentation"]',
      '[role="log"]',
      '[role="article"]',
    ];

    for (const sel of checks) {
      try {
        const els = document.querySelectorAll(sel);
        if (els.length > 0) {
          result[sel] = {
            count: els.length,
            samples: [...els].slice(0, 3).map((el) => ({
              tag: el.tagName,
              id: el.id || undefined,
              class: el.className && typeof el.className === 'string' ? el.className.slice(0, 100) : undefined,
              text: el.textContent?.slice(0, 80),
              children: el.children.length,
            })),
          };
        }
      } catch {}
    }

    // 扫描 body 下的主要结构
    result._bodyChildren = [...document.body.children].map((el) => ({
      tag: el.tagName,
      id: el.id,
      class: (typeof el.className === 'string' ? el.className : '').slice(0, 80),
    }));

    return result;
  });

  for (const [sel, info] of Object.entries(probe)) {
    if (sel === '_bodyChildren') {
      console.log(`  body 直接子元素:`);
      info.forEach((c) => console.log(`    <${c.tag}> #${c.id} .${c.class}`));
    } else {
      console.log(`  ✅ ${sel}: ${info.count} 个`);
      info.samples?.forEach((s) => console.log(`    <${s.tag}> ${s.class?.slice(0, 60)} "${s.text?.slice(0, 40)}..."`));
    }
  }

  // 检查面板
  const panel2 = await page2.$('#cgpt-nav-panel');
  console.log(`\n  面板: ${panel2 ? '✅ 存在' : '❌ 不存在'}`);

  if (panel2) {
    const items = await page2.$$eval('.cgpt-nav-item', (els) =>
      els.map((e) => ({ type: e.dataset.type, level: e.dataset.level, text: e.textContent.slice(0, 50) }))
    );
    console.log(`  导航条目: ${items.length}`);
    items.forEach((item, i) => console.log(`    [${i}] ${item.type}${item.level ? '(h' + item.level + ')' : ''}: ${item.text}`));

    // 测试点击
    if (items.length > 1) {
      await page2.click('.cgpt-nav-item:nth-child(2)');
      await new Promise((r) => setTimeout(r, 1000));
      console.log('  ✅ 点击导航条目 - 无异常');
    }

    // 测试导出
    const downloadDir = path.join(__dirname, 'test-downloads');
    fs.mkdirSync(downloadDir, { recursive: true });
    const client = await page2.createCDPSession();
    await client.send('Page.setDownloadBehavior', { behavior: 'allow', downloadPath: downloadDir });
    await page2.click('#cgpt-nav-export-btn');
    await new Promise((r) => setTimeout(r, 2000));
    const downloads = fs.readdirSync(downloadDir);
    console.log(`  导出: ${downloads.length > 0 ? '✅ 文件已下载: ' + downloads.join(', ') : '⚠️ 无下载文件'}`);
  }

  const ss2 = path.join(__dirname, 'test-screenshot-live.png');
  await page2.screenshot({ path: ss2, fullPage: false });
  console.log(`  截图: ${ss2}`);

  console.log('\n=== 验证完成 ===');
  await browser.close();
}

test().catch((err) => {
  console.error('测试失败:', err.message);
  process.exit(1);
});

