/**
 * 使用 Puppeteer 加载扩展并验证功能
 * 方案: 本地 HTTP 服务器 + Chrome --host-rules 将 chatgpt.com 指向 localhost
 */
import { createRequire } from 'module';
import path from 'path';
import fs from 'fs';
import http from 'http';
import { fileURLToPath } from 'url';

const require = createRequire('/Users/leon/Library/pnpm/global/5/node_modules/puppeteer/');
const puppeteer = require('puppeteer');

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const EXTENSION_PATH = __dirname;
const CHROME_PATH = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const TEST_HTML = fs.readFileSync(path.join(__dirname, 'test-page.html'), 'utf-8');
const PORT = 18923;

async function test() {
  console.log('=== ChatGPT Navigator 插件验证 ===\n');

  // 启动本地服务器
  const server = http.createServer((req, res) => {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(TEST_HTML);
  });
  await new Promise((resolve) => server.listen(PORT, resolve));
  console.log(`本地服务器: http://localhost:${PORT}`);

  const browser = await puppeteer.launch({
    headless: false,
    executablePath: CHROME_PATH,
    args: [
      `--disable-extensions-except=${EXTENSION_PATH}`,
      `--load-extension=${EXTENSION_PATH}`,
      '--no-first-run',
      '--disable-default-apps',
      // 将 chatgpt.com 解析到 localhost
      `--host-resolver-rules=MAP chatgpt.com 127.0.0.1:${PORT}`,
      '--ignore-certificate-errors',
    ],
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900 });

  // 收集日志
  const logs = [];
  page.on('console', (msg) => logs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => logs.push(`[PAGE_ERROR] ${err.message}`));

  // 导航到 chatgpt.com（实际由本地服务器响应）
  const testUrl = `http://chatgpt.com:${PORT}/share/test-conversation-123`;
  console.log(`导航到: ${testUrl}\n`);
  await page.goto(testUrl, { waitUntil: 'load', timeout: 15000 });
  // 等待 content script (document_idle) 注入
  await new Promise((r) => setTimeout(r, 3000));

  // === 验证 DOM 选择器 ===
  console.log('--- DOM 选择器 ---');
  const selectorResults = {};
  for (const [name, sel] of Object.entries({
    '所有消息': '[data-message-author-role]',
    '用户消息': '[data-message-author-role="user"]',
    '助手消息': '[data-message-author-role="assistant"]',
    'markdown': '.markdown',
    '用户文本': '.whitespace-pre-wrap',
    '标题h1-h6': '.markdown h1, .markdown h2, .markdown h3, .markdown h4, .markdown h5, .markdown h6',
  })) {
    const count = await page.$$eval(sel, (els) => els.length).catch(() => 0);
    selectorResults[name] = count;
    console.log(`  ${count > 0 ? '✅' : '❌'} ${name}: ${count}`);
  }

  // === 验证面板 ===
  console.log('\n--- 导航面板 ---');
  let panelEl = await page.$('#cgpt-nav-panel');

  if (!panelEl) {
    // 可能 manifest matches 只匹配 https，尝试 https
    console.log('  面板未出现（可能 http 不匹配 manifest 的 https 规则）');
    console.log('  尝试手动注入 content script...');
    await page.addStyleTag({ path: path.join(__dirname, 'styles.css') });
    await page.addScriptTag({ path: path.join(__dirname, 'content.js') });
    await new Promise((r) => setTimeout(r, 2000));
    panelEl = await page.$('#cgpt-nav-panel');
  }

  console.log(`  ${panelEl ? '✅' : '❌'} 面板存在: ${!!panelEl}`);

  if (!panelEl) {
    // 最后手段：检查 URL 匹配
    const urlCheck = await page.evaluate(() => ({
      href: location.href,
      pathname: location.pathname,
      host: location.host,
    }));
    console.log(`  URL: ${JSON.stringify(urlCheck)}`);
    console.log('  控制台:');
    logs.forEach((l) => console.log(`    ${l}`));
    await page.screenshot({ path: path.join(__dirname, 'test-screenshot.png') });
    server.close();
    await browser.close();
    process.exit(1);
  }

  // 面板尺寸
  const panelStyle = await page.$eval('#cgpt-nav-panel', (el) => ({
    w: el.offsetWidth, h: el.offsetHeight, display: getComputedStyle(el).display,
  }));
  console.log(`  尺寸: ${panelStyle.w}x${panelStyle.h}, display=${panelStyle.display}`);

  // === 验证导航条目 ===
  console.log('\n--- 导航条目 ---');
  const navItems = await page.$$eval('.cgpt-nav-item', (els) =>
    els.map((e) => ({ type: e.dataset.type, level: e.dataset.level, text: e.textContent.slice(0, 70) }))
  );

  const userItems = navItems.filter((i) => i.type === 'user').length;
  const headingItems = navItems.filter((i) => i.type === 'heading').length;
  console.log(`  总数: ${navItems.length} (用户: ${userItems}, 标题: ${headingItems})`);
  console.log(`  ${userItems === selectorResults['用户消息'] ? '✅' : '❌'} 用户条目: ${userItems}/${selectorResults['用户消息']}`);
  console.log(`  ${headingItems === selectorResults['标题h1-h6'] ? '✅' : '❌'} 标题条目: ${headingItems}/${selectorResults['标题h1-h6']}`);

  navItems.forEach((item, i) =>
    console.log(`  [${String(i).padStart(2)}] ${item.type.padEnd(7)} ${item.level ? 'h' + item.level + ' ' : '   '} ${item.text}`)
  );

  // === 点击滚动 ===
  console.log('\n--- 点击滚动 ---');
  if (navItems.length >= 3) {
    const lastIdx = navItems.length;
    await page.click(`.cgpt-nav-item:nth-child(${lastIdx})`);
    await new Promise((r) => setTimeout(r, 1500));

    const activeText = await page.$eval('.cgpt-nav-item.active', (el) => el.textContent.slice(0, 50)).catch(() => null);
    console.log(`  ${activeText ? '✅' : '❌'} active 高亮: "${activeText}"`);

    const scrollY = await page.evaluate(() => window.scrollY);
    console.log(`  ${scrollY > 0 ? '✅' : 'ℹ️'} 页面滚动: scrollY=${scrollY}`);
  }

  // === 折叠/展开 ===
  console.log('\n--- 折叠/展开 ---');
  await page.click('#cgpt-nav-toggle');
  await new Promise((r) => setTimeout(r, 500));
  const isCollapsed = await page.$eval('#cgpt-nav-panel', (el) => el.classList.contains('collapsed'));
  const toggleChar = await page.$eval('#cgpt-nav-toggle', (el) => el.textContent);
  console.log(`  ${isCollapsed && toggleChar === '▶' ? '✅' : '❌'} 折叠: collapsed=${isCollapsed}, btn="${toggleChar}"`);

  await page.click('#cgpt-nav-toggle');
  await new Promise((r) => setTimeout(r, 500));
  const isExpanded = await page.$eval('#cgpt-nav-panel', (el) => !el.classList.contains('collapsed'));
  console.log(`  ${isExpanded ? '✅' : '❌'} 展开恢复`);

  // === Markdown 导出 ===
  console.log('\n--- Markdown 导出 ---');
  const downloadDir = path.join(__dirname, 'test-downloads');
  fs.mkdirSync(downloadDir, { recursive: true });
  fs.readdirSync(downloadDir).forEach((f) => fs.unlinkSync(path.join(downloadDir, f)));

  const client = await page.createCDPSession();
  await client.send('Page.setDownloadBehavior', { behavior: 'allow', downloadPath: downloadDir });
  await page.click('#cgpt-nav-export-btn');
  await new Promise((r) => setTimeout(r, 3000));

  const downloads = fs.readdirSync(downloadDir);
  console.log(`  ${downloads.length > 0 ? '✅' : '❌'} 文件: ${downloads.length > 0 ? downloads.join(', ') : '无'}`);

  if (downloads.length > 0) {
    const md = fs.readFileSync(path.join(downloadDir, downloads[0]), 'utf-8');
    const lines = md.split('\n');
    console.log(`  行数: ${lines.length}`);

    const checks = [
      ['一级标题 #', lines.some((l) => /^# /.test(l))],
      ['二级标题 ##', lines.some((l) => /^## /.test(l))],
      ['三级标题 ###', lines.some((l) => /^### /.test(l))],
      ['代码块 ```', lines.some((l) => /^```/.test(l))],
      ['加粗 **', md.includes('**')],
      ['分隔线 ---', lines.some((l) => l.trim() === '---')],
      ['User 标记', md.includes('User')],
      ['Assistant 标记', md.includes('Assistant')],
      ['表格 |', lines.some((l) => /^\|/.test(l))],
      ['无序列表 -', lines.some((l) => /^- /.test(l))],
      ['有序列表', lines.some((l) => /^\d+\. /.test(l))],
      ['链接 []()', md.includes('](')],
      ['行内代码 `', /`[^`]+`/.test(md)],
      ['斜体 *', /(?<!\*)\*[^*]+\*(?!\*)/.test(md)],
      ['删除线 ~~', md.includes('~~')],
      ['引用 >', lines.some((l) => /^> /.test(l))],
    ];
    for (const [desc, pass] of checks) {
      console.log(`  ${pass ? '✅' : '❌'} ${desc}`);
    }

    console.log('\n  --- 导出预览 (前40行) ---');
    lines.slice(0, 40).forEach((l) => console.log(`  | ${l}`));
    if (lines.length > 40) console.log(`  | ... (共 ${lines.length} 行)`);
  }

  // === MutationObserver ===
  console.log('\n--- MutationObserver 动态更新 ---');
  const countBefore = await page.$$eval('.cgpt-nav-item', (els) => els.length);

  await page.evaluate(() => {
    const container = document.querySelector('[role="presentation"]');
    const msg = document.createElement('div');
    msg.className = 'message';
    msg.setAttribute('data-message-author-role', 'user');
    msg.innerHTML = '<div class="whitespace-pre-wrap">动态插入的测试消息</div>';
    container.appendChild(msg);
  });

  await new Promise((r) => setTimeout(r, 1500));
  const countAfter = await page.$$eval('.cgpt-nav-item', (els) => els.length);
  console.log(`  条目: ${countBefore} → ${countAfter}`);
  console.log(`  ${countAfter > countBefore ? '✅' : '❌'} 自动刷新: ${countAfter > countBefore ? '成功' : '失败'}`);

  // 截图
  const ssPath = path.join(__dirname, 'test-screenshot.png');
  await page.screenshot({ path: ssPath, fullPage: false });
  console.log(`\n截图: ${ssPath}`);

  if (logs.length > 0) {
    console.log('\n--- 控制台日志 ---');
    logs.slice(0, 20).forEach((l) => console.log(`  ${l}`));
  }

  console.log('\n=== 验证完成 ===');
  server.close();
  await browser.close();
}

test().catch((err) => {
  console.error('测试失败:', err.message);
  process.exit(1);
});

