/**
 * 使用 Puppeteer 加载扩展并验证功能
 * 通过请求拦截将 chatgpt.com/share/xxx 映射到本地测试页面
 * 这样 content_scripts 的 matches 和 isConversationPage 都能正常工作
 */
import { createRequire } from 'module';
import path from 'path';
import fs from 'fs';
import { fileURLToPath } from 'url';

const require = createRequire('/Users/leon/Library/pnpm/global/5/node_modules/puppeteer/');
const puppeteer = require('puppeteer');

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const EXTENSION_PATH = __dirname;
const CHROME_PATH = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const TEST_HTML = fs.readFileSync(path.join(__dirname, 'test-page.html'), 'utf-8');
const FAKE_URL = 'https://chatgpt.com/share/test-conversation-123';

async function test() {
  console.log('=== ChatGPT Navigator 插件验证 ===\n');

  const browser = await puppeteer.launch({
    headless: false,
    executablePath: CHROME_PATH,
    args: [
      `--disable-extensions-except=${EXTENSION_PATH}`,
      `--load-extension=${EXTENSION_PATH}`,
      '--no-first-run',
      '--disable-default-apps',
    ],
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900 });

  // 拦截请求，把 chatgpt.com 的响应替换为本地 HTML
  await page.setRequestInterception(true);
  page.on('request', (req) => {
    if (req.url() === FAKE_URL) {
      req.respond({
        status: 200,
        contentType: 'text/html; charset=utf-8',
        body: TEST_HTML,
      });
    } else {
      req.continue();
    }
  });

  // 收集 console 日志
  const logs = [];
  page.on('console', (msg) => logs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => logs.push(`[ERROR] ${err.message}`));

  // 导航到伪造的 chatgpt.com/share URL → 触发 content_scripts 注入
  console.log(`1. 导航到 ${FAKE_URL}`);
  await page.goto(FAKE_URL, { waitUntil: 'load' });
  console.log('   等待扩展注入...');
  await new Promise((r) => setTimeout(r, 3000));

  // === 验证 DOM 选择器 ===
  console.log('\n--- DOM 选择器 ---');
  const selectorResults = {};
  for (const [name, sel] of Object.entries({
    '所有消息': '[data-message-author-role]',
    '用户消息': '[data-message-author-role="user"]',
    '助手消息': '[data-message-author-role="assistant"]',
    'markdown 区域': '.markdown',
    '用户文本': '.whitespace-pre-wrap',
    '标题 (h1-h6)': '.markdown h1, .markdown h2, .markdown h3, .markdown h4, .markdown h5, .markdown h6',
  })) {
    const count = await page.$$eval(sel, (els) => els.length).catch(() => 0);
    selectorResults[name] = count;
    console.log(`  ${count > 0 ? '✅' : '❌'} ${name}: ${count}`);
  }

  // === 验证面板 ===
  console.log('\n--- 导航面板 ---');
  const panelEl = await page.$('#cgpt-nav-panel');
  console.log(`  ${panelEl ? '✅' : '❌'} 面板存在: ${!!panelEl}`);

  if (!panelEl) {
    console.log('  ⚠️ 面板未创建，控制台日志:');
    logs.forEach((l) => console.log(`    ${l}`));
    console.log('\n  检查 URL 匹配:');
    const urlCheck = await page.evaluate(() => {
      const p = location.pathname;
      return {
        pathname: p,
        matchShare: /^\/(c|share|g)\/[a-zA-Z0-9-]+/.test(p),
        matchUUID: /^\/[a-f0-9-]{36}/.test(p),
      };
    });
    console.log(`    ${JSON.stringify(urlCheck)}`);

    // 截图后退出
    await page.screenshot({ path: path.join(__dirname, 'test-screenshot.png') });
    await browser.close();
    process.exit(1);
  }

  // 面板可见性
  const panelStyle = await page.$eval('#cgpt-nav-panel', (el) => {
    const s = getComputedStyle(el);
    return { display: s.display, width: el.offsetWidth, height: el.offsetHeight, opacity: s.opacity };
  });
  console.log(`  面板尺寸: ${panelStyle.width}x${panelStyle.height}, display=${panelStyle.display}`);

  // === 验证导航条目 ===
  console.log('\n--- 导航条目 ---');
  const navItems = await page.$$eval('.cgpt-nav-item', (els) =>
    els.map((e) => ({
      type: e.dataset.type,
      level: e.dataset.level,
      text: e.textContent.slice(0, 70),
    }))
  );
  console.log(`  总数: ${navItems.length}`);
  const expectedUserCount = selectorResults['用户消息'];
  const actualUserItems = navItems.filter((i) => i.type === 'user').length;
  const headingItems = navItems.filter((i) => i.type === 'heading').length;
  console.log(`  用户条目: ${actualUserItems} (期望 ${expectedUserCount})`);
  console.log(`  标题条目: ${headingItems} (期望 ${selectorResults['标题 (h1-h6)']})`);
  console.log(`  ${actualUserItems === expectedUserCount ? '✅' : '❌'} 用户条目数匹配`);
  console.log(`  ${headingItems === selectorResults['标题 (h1-h6)'] ? '✅' : '❌'} 标题条目数匹配`);

  navItems.forEach((item, i) =>
    console.log(`  [${i}] ${item.type}${item.level ? ' h' + item.level : ''}: ${item.text}`)
  );

  // === 验证点击滚动 ===
  console.log('\n--- 点击滚动 ---');
  if (navItems.length >= 3) {
    // 点击最后一个条目（应该滚到底部）
    const lastIdx = navItems.length;
    await page.click(`.cgpt-nav-item:nth-child(${lastIdx})`);
    await new Promise((r) => setTimeout(r, 1500));

    // 检查是否有 active 状态
    const activeItem = await page.$eval('.cgpt-nav-item.active', (el) => el.textContent.slice(0, 40)).catch(() => null);
    console.log(`  ${activeItem ? '✅' : '❌'} active 状态: "${activeItem}"`);

    // 检查页面是否滚动
    const scrolled = await page.evaluate(() => window.scrollY > 0);
    console.log(`  ${scrolled ? '✅' : 'ℹ️'} 页面滚动: scrollY=${await page.evaluate(() => window.scrollY)}`);
  }

  // === 验证折叠/展开 ===
  console.log('\n--- 折叠/展开 ---');
  await page.click('#cgpt-nav-toggle');
  await new Promise((r) => setTimeout(r, 500));
  const collapsed = await page.$eval('#cgpt-nav-panel', (el) => el.classList.contains('collapsed'));
  console.log(`  ${collapsed ? '✅' : '❌'} 折叠: ${collapsed}`);
  const toggleText = await page.$eval('#cgpt-nav-toggle', (el) => el.textContent);
  console.log(`  ${toggleText === '▶' ? '✅' : '❌'} 按钮文字: "${toggleText}"`);

  await page.click('#cgpt-nav-toggle');
  await new Promise((r) => setTimeout(r, 500));
  const expanded = await page.$eval('#cgpt-nav-panel', (el) => !el.classList.contains('collapsed'));
  console.log(`  ${expanded ? '✅' : '❌'} 展开: ${expanded}`);

  // === 验证导出 ===
  console.log('\n--- Markdown 导出 ---');
  const downloadDir = path.join(__dirname, 'test-downloads');
  fs.mkdirSync(downloadDir, { recursive: true });
  // 清空旧文件
  fs.readdirSync(downloadDir).forEach((f) => fs.unlinkSync(path.join(downloadDir, f)));

  const client = await page.createCDPSession();
  await client.send('Page.setDownloadBehavior', { behavior: 'allow', downloadPath: downloadDir });
  await page.click('#cgpt-nav-export-btn');
  await new Promise((r) => setTimeout(r, 3000));

  const downloads = fs.readdirSync(downloadDir);
  console.log(`  ${downloads.length > 0 ? '✅' : '❌'} 下载文件: ${downloads.length > 0 ? downloads.join(', ') : '无'}`);

  if (downloads.length > 0) {
    const mdContent = fs.readFileSync(path.join(downloadDir, downloads[0]), 'utf-8');
    const lines = mdContent.split('\n');
    console.log(`  文件行数: ${lines.length}`);

    // 检查 markdown 格式
    const checks = {
      '包含一级标题 #': lines.some((l) => /^# /.test(l)),
      '包含二级标题 ##': lines.some((l) => /^## /.test(l)),
      '包含三级标题 ###': lines.some((l) => /^### /.test(l)),
      '包含代码块 ```': lines.some((l) => /^```/.test(l)),
      '包含加粗 **': mdContent.includes('**'),
      '包含分隔线 ---': lines.some((l) => l.trim() === '---'),
      '包含用户标记': mdContent.includes('User'),
      '包含助手标记': mdContent.includes('Assistant'),
      '包含表格 |': lines.some((l) => /^\|/.test(l)),
      '包含列表 -': lines.some((l) => /^- /.test(l)),
      '包含有序列表': lines.some((l) => /^\d+\. /.test(l)),
      '包含链接 []()': mdContent.includes(']('),
      '包含行内代码 `': /`[^`]+`/.test(mdContent),
    };

    for (const [desc, pass] of Object.entries(checks)) {
      console.log(`  ${pass ? '✅' : '❌'} ${desc}`);
    }

    // 打印前30行预览
    console.log('\n  --- 导出内容预览 (前30行) ---');
    lines.slice(0, 30).forEach((l) => console.log(`  ${l}`));
    console.log('  ...');
  }

  // === 验证 MutationObserver（动态内容） ===
  console.log('\n--- MutationObserver 动态更新 ---');
  const itemsBefore = await page.$$eval('.cgpt-nav-item', (els) => els.length);

  // 动态插入一条新用户消息
  await page.evaluate(() => {
    const container = document.querySelector('[role="presentation"]');
    const newMsg = document.createElement('div');
    newMsg.className = 'message';
    newMsg.setAttribute('data-message-author-role', 'user');
    newMsg.setAttribute('data-message-id', 'msg-dynamic');
    newMsg.innerHTML = '<div class="whitespace-pre-wrap">这是动态插入的消息，用于测试 MutationObserver</div>';
    container.appendChild(newMsg);
  });

  // 等待防抖刷新（500ms + 余量）
  await new Promise((r) => setTimeout(r, 1500));

  const itemsAfter = await page.$$eval('.cgpt-nav-item', (els) => els.length);
  console.log(`  条目变化: ${itemsBefore} → ${itemsAfter}`);
  console.log(`  ${itemsAfter > itemsBefore ? '✅' : '❌'} MutationObserver 自动刷新`);

  // 截图
  const ssPath = path.join(__dirname, 'test-screenshot.png');
  await page.screenshot({ path: ssPath, fullPage: false });
  console.log(`\n截图: ${ssPath}`);

  // 控制台日志
  if (logs.length > 0) {
    console.log('\n--- 控制台日志 ---');
    logs.forEach((l) => console.log(`  ${l}`));
  }

  // === 汇总 ===
  console.log('\n=== 验证完成 ===');
  await browser.close();
}

test().catch((err) => {
