  const browser = await puppeteer.launch({
    headless: false,
    executablePath: CHROME_PATH,
    args: [
      `--disable-extensions-except=${EXTENSION_PATH}`,
      `--load-extension=${EXTENSION_PATH}`,
      '--no-first-run',
      '--disable-default-apps',
      // 将 chatgpt.com 解析到 localhost
      `--host-resolver-rules=MAP chatgpt.com 127.0.0.1:${PORT}`,
      '--ignore-certificate-errors',
    ],
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900 });

  // 收集日志
  const logs = [];
  page.on('console', (msg) => logs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => logs.push(`[PAGE_ERROR] ${err.message}`));

  // 导航到 chatgpt.com（实际由本地服务器响应）
  const testUrl = `http://chatgpt.com:${PORT}/share/test-conversation-123`;
  console.log(`导航到: ${testUrl}\n`);
  await page.goto(testUrl, { waitUntil: 'load', timeout: 15000 });
  // 等待 content script (document_idle) 注入
  await new Promise((r) => setTimeout(r, 3000));

  // === 验证 DOM 选择器 ===
