    console.log(`  ${activeText ? '✅' : '❌'} active 高亮: "${activeText}"`);

    const scrollY = await page.evaluate(() => window.scrollY);
    console.log(`  ${scrollY > 0 ? '✅' : 'ℹ️'} 页面滚动: scrollY=${scrollY}`);
  }

  // === 折叠/展开 ===
  console.log('\n--- 折叠/展开 ---');
  await page.click('#cgpt-nav-toggle');
  await new Promise((r) => setTimeout(r, 500));
  const isCollapsed = await page.$eval('#cgpt-nav-panel', (el) => el.classList.contains('collapsed'));
  const toggleChar = await page.$eval('#cgpt-nav-toggle', (el) => el.textContent);
  console.log(`  ${isCollapsed && toggleChar === '▶' ? '✅' : '❌'} 折叠: collapsed=${isCollapsed}, btn="${toggleChar}"`);

  await page.click('#cgpt-nav-toggle');
  await new Promise((r) => setTimeout(r, 500));
  const isExpanded = await page.$eval('#cgpt-nav-panel', (el) => !el.classList.contains('collapsed'));
  console.log(`  ${isExpanded ? '✅' : '❌'} 展开恢复`);

  // === Markdown 导出 ===
  console.log('\n--- Markdown 导出 ---');
  const downloadDir = path.join(__dirname, 'test-downloads');
  fs.mkdirSync(downloadDir, { recursive: true });
  fs.readdirSync(downloadDir).forEach((f) => fs.unlinkSync(path.join(downloadDir, f)));

  const client = await page.createCDPSession();
  await client.send('Page.setDownloadBehavior', { behavior: 'allow', downloadPath: downloadDir });
  await page.click('#cgpt-nav-export-btn');
  await new Promise((r) => setTimeout(r, 3000));

  const downloads = fs.readdirSync(downloadDir);
  console.log(`  ${downloads.length > 0 ? '✅' : '❌'} 文件: ${downloads.length > 0 ? downloads.join(', ') : '无'}`);

  if (downloads.length > 0) {
    const md = fs.readFileSync(path.join(downloadDir, downloads[0]), 'utf-8');
    const lines = md.split('\n');
    console.log(`  行数: ${lines.length}`);

    const checks = [
      ['一级标题 #', lines.some((l) => /^# /.test(l))],
      ['二级标题 ##', lines.some((l) => /^## /.test(l))],
      ['三级标题 ###', lines.some((l) => /^### /.test(l))],
      ['代码块 ```', lines.some((l) => /^```/.test(l))],
      ['加粗 **', md.includes('**')],
      ['分隔线 ---', lines.some((l) => l.trim() === '---')],
      ['User 标记', md.includes('User')],
      ['Assistant 标记', md.includes('Assistant')],
      ['表格 |', lines.some((l) => /^\|/.test(l))],
      ['无序列表 -', lines.some((l) => /^- /.test(l))],
      ['有序列表', lines.some((l) => /^\d+\. /.test(l))],
      ['链接 []()', md.includes('](')],
      ['行内代码 `', /`[^`]+`/.test(md)],
      ['斜体 *', /(?<!\*)\*[^*]+\*(?!\*)/.test(md)],
      ['删除线 ~~', md.includes('~~')],
      ['引用 >', lines.some((l) => /^> /.test(l))],
    ];
    for (const [desc, pass] of checks) {
      console.log(`  ${pass ? '✅' : '❌'} ${desc}`);
    }

    console.log('\n  --- 导出预览 (前40行) ---');
    lines.slice(0, 40).forEach((l) => console.log(`  | ${l}`));
    if (lines.length > 40) console.log(`  | ... (共 ${lines.length} 行)`);
  }

  // === MutationObserver ===
  console.log('\n--- MutationObserver 动态更新 ---');
  const countBefore = await page.$$eval('.cgpt-nav-item', (els) => els.length);

  await page.evaluate(() => {
    const container = document.querySelector('[role="presentation"]');
    const msg = document.createElement('div');
    msg.className = 'message';
    msg.setAttribute('data-message-author-role', 'user');
    msg.innerHTML = '<div class="whitespace-pre-wrap">动态插入的测试消息</div>';
    container.appendChild(msg);
  });

  await new Promise((r) => setTimeout(r, 1500));
  const countAfter = await page.$$eval('.cgpt-nav-item', (els) => els.length);
  console.log(`  条目: ${countBefore} → ${countAfter}`);
  console.log(`  ${countAfter > countBefore ? '✅' : '❌'} 自动刷新: ${countAfter > countBefore ? '成功' : '失败'}`);

  // 截图
  const ssPath = path.join(__dirname, 'test-screenshot.png');
  await page.screenshot({ path: ssPath, fullPage: false });
  console.log(`\n截图: ${ssPath}`);

  if (logs.length > 0) {
    console.log('\n--- 控制台日志 ---');
    logs.slice(0, 20).forEach((l) => console.log(`  ${l}`));
  }

  console.log('\n=== 验证完成 ===');
  server.close();
  await browser.close();
}

test().catch((err) => {
  console.error('测试失败:', err.message);
  process.exit(1);
});

