/* ChatGPT Navigator - 浮动导航面板 */

#cgpt-nav-panel {
  position: fixed;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 280px;
  max-height: 70vh;
  background: rgba(30, 30, 30, 0.88);
