  border-radius: 0 12px 12px 0;
  box-shadow: 2px 4px 20px rgba(0, 0, 0, 0.3);
  z-index: 10000;
  display: flex;
  flex-direction: column;
  transition: transform 0.3s ease, opacity 0.3s ease;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: #e0e0e0;
  user-select: none;
}

#cgpt-nav-panel.collapsed {
  transform: translateY(-50%) translateX(-260px);
}

#cgpt-nav-panel.collapsed #cgpt-nav-toggle {
  border-radius: 0 8px 8px 0;
}

/* 标题栏 */
#cgpt-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  flex-shrink: 0;
}

#cgpt-nav-header span {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.5px;
}

/* 折叠按钮 */
#cgpt-nav-toggle {
  position: absolute;
  right: -28px;
  top: 50%;
  transform: translateY(-50%);
  width: 28px;
  height: 56px;
  background: rgba(30, 30, 30, 0.88);
  backdrop-filter: blur(12px);
  border: none;
  border-radius: 0 8px 8px 0;
  color: #e0e0e0;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  transition: background 0.2s;
}

#cgpt-nav-toggle:hover {
  background: rgba(60, 60, 60, 0.95);
}

/* 目录内容区 */
#cgpt-nav-list {
  flex: 1;
  overflow-y: auto;
  padding: 8px 0;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) transparent;
}

#cgpt-nav-list::-webkit-scrollbar {
  width: 4px;
}

#cgpt-nav-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 2px;
}

/* 导航条目 */
.cgpt-nav-item {
  padding: 6px 14px;
  font-size: 12px;
  line-height: 1.5;
  cursor: pointer;
  transition: background 0.15s;
  border-left: 3px solid transparent;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.cgpt-nav-item:hover {
  background: rgba(255, 255, 255, 0.08);
}

.cgpt-nav-item.active {
  background: rgba(255, 255, 255, 0.1);
  border-left-color: #10a37f;
}

/* 用户消息条目 */
.cgpt-nav-item[data-type="user"] {
  color: #7cc8f8;
  font-weight: 600;
  padding-left: 14px;
}

.cgpt-nav-item[data-type="user"]::before {
  content: "👤 ";
  font-size: 11px;
}

/* 标题条目 - 按层级缩进 */
.cgpt-nav-item[data-type="heading"] {
  color: #c8c8c8;
}

.cgpt-nav-item[data-type="heading"]::before {
  content: "§ ";
  color: #10a37f;
  font-weight: bold;
}

.cgpt-nav-item[data-level="1"] { padding-left: 18px; font-size: 13px; font-weight: 600; }
.cgpt-nav-item[data-level="2"] { padding-left: 26px; font-size: 12px; font-weight: 500; }
.cgpt-nav-item[data-level="3"] { padding-left: 34px; font-size: 12px; }
.cgpt-nav-item[data-level="4"] { padding-left: 42px; font-size: 11px; }
.cgpt-nav-item[data-level="5"] { padding-left: 50px; font-size: 11px; }
.cgpt-nav-item[data-level="6"] { padding-left: 58px; font-size: 11px; }

/* 底部操作栏 */
#cgpt-nav-footer {
  padding: 10px 14px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  flex-shrink: 0;
}

#cgpt-nav-export-btn {
  width: 100%;
  padding: 8px 12px;
  background: #10a37f;
  color: white;
  border: none;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
}

#cgpt-nav-export-btn:hover {
  background: #0d8c6d;
}

#cgpt-nav-export-btn:active {
  background: #0a7a5e;
}

/* 空状态 */
