  if (!panelEl) {
    console.log('ℹ️ 面板未自动创建（URL 非 chatgpt.com，isConversationPage 返回 false）');
    console.log('  手动在页面中执行 createPanel 逻辑...\n');

    // 由于 content.js 是 IIFE，函数不暴露。重新注入一个简化版用于测试
    await page.evaluate(() => {
      // 直接创建面板 — 模拟 content.js 中的 createPanel
      if (document.getElementById('cgpt-nav-panel')) return;

      const panel = document.createElement('div');
      panel.id = 'cgpt-nav-panel';
      panel.innerHTML = `
        <div id="cgpt-nav-header"><span>📑 会话导航</span></div>
        <button id="cgpt-nav-toggle" title="收起/展开">◀</button>
        <div id="cgpt-nav-list"></div>
        <div id="cgpt-nav-footer">
          <button id="cgpt-nav-export-btn">📥 导出为 Markdown</button>
        </div>
      `;
      document.body.appendChild(panel);
    });

    // 这种方式无法测试完整逻辑。更好的办法是让 content.js 暴露接口。
    // 换个思路：修改 content.js 后再注入。
    console.log('  → 重新加载修改后的 content.js (绕过 URL 检查)...\n');

    // 读取 content.js 并 patch isConversationPage
    let jsCode = fs.readFileSync(path.join(__dirname, 'content.js'), 'utf-8');
    jsCode = jsCode.replace(
      'function isConversationPage() {',
      'function isConversationPage() { if (true) return true; // TEST PATCH'
    );

    // 移除已存在的面板
    await page.evaluate(() => {
      const existing = document.getElementById('cgpt-nav-panel');
      if (existing) existing.remove();
    });

    // 注入 patched 版本
    await page.evaluate(jsCode);
    await new Promise((r) => setTimeout(r, 2000));
    panelEl = await page.$('#cgpt-nav-panel');
  }

  // === DOM 选择器 ===
  console.log('--- DOM 选择器 ---');
  const selectorResults = {};
  for (const [name, sel] of Object.entries({
    '所有消息': '[data-message-author-role]',
    '用户消息': '[data-message-author-role="user"]',
    '助手消息': '[data-message-author-role="assistant"]',
    'markdown': '.markdown',
    '用户文本': '.whitespace-pre-wrap',
    '标题h1-h6': '.markdown h1, .markdown h2, .markdown h3, .markdown h4, .markdown h5, .markdown h6',
  })) {
    const count = await page.$$eval(sel, (els) => els.length).catch(() => 0);
    selectorResults[name] = count;
    console.log(`  ${count > 0 ? '✅' : '❌'} ${name}: ${count}`);
  }

  // === 面板 ===
  console.log('\n--- 导航面板 ---');
  console.log(`  ${panelEl ? '✅' : '❌'} 面板存在: ${!!panelEl}`);

  if (!panelEl) {
    console.log('  控制台日志:');
    logs.forEach((l) => console.log(`    ${l}`));
    await page.screenshot({ path: path.join(__dirname, 'test-screenshot.png') });
    server.close();
    await browser.close();
    process.exit(1);
  }

  const panelStyle = await page.$eval('#cgpt-nav-panel', (el) => ({
    w: el.offsetWidth, h: el.offsetHeight,
  }));
  console.log(`  尺寸: ${panelStyle.w}x${panelStyle.h}`);

  // === 导航条目 ===
  console.log('\n--- 导航条目 ---');
  const navItems = await page.$$eval('.cgpt-nav-item', (els) =>
    els.map((e) => ({ type: e.dataset.type, level: e.dataset.level, text: e.textContent.slice(0, 70) }))
  );

  const userItems = navItems.filter((i) => i.type === 'user').length;
  const headingItems = navItems.filter((i) => i.type === 'heading').length;
  console.log(`  ${userItems === selectorResults['用户消息'] ? '✅' : '❌'} 用户条目: ${userItems}/${selectorResults['用户消息']}`);
  console.log(`  ${headingItems === selectorResults['标题h1-h6'] ? '✅' : '❌'} 标题条目: ${headingItems}/${selectorResults['标题h1-h6']}`);

  navItems.forEach((item, i) =>
    console.log(`  [${String(i).padStart(2)}] ${(item.type + (item.level ? ' h' + item.level : '')).padEnd(12)} ${item.text}`)
  );

  // === 点击滚动 ===
  console.log('\n--- 点击滚动 ---');
  if (navItems.length >= 3) {
    const idx = navItems.length;
    await page.click(`.cgpt-nav-item:nth-child(${idx})`);
    await new Promise((r) => setTimeout(r, 1500));
    const active = await page.$eval('.cgpt-nav-item.active', (el) => el.textContent.slice(0, 50)).catch(() => null);
    console.log(`  ${active ? '✅' : '❌'} active 高亮: "${active}"`);
    const sy = await page.evaluate(() => window.scrollY);
    console.log(`  ${sy > 0 ? '✅' : 'ℹ️'} scrollY=${sy}`);
  }

  // === 折叠/展开 ===
  console.log('\n--- 折叠/展开 ---');
  await page.click('#cgpt-nav-toggle');
  await new Promise((r) => setTimeout(r, 500));
  const collapsed = await page.$eval('#cgpt-nav-panel', (el) => el.classList.contains('collapsed'));
  const btn = await page.$eval('#cgpt-nav-toggle', (el) => el.textContent);
  console.log(`  ${collapsed && btn === '◀' ? '✅' : '❌'} 折叠: collapsed=${collapsed}, btn="${btn}"`);

  await page.click('#cgpt-nav-toggle');
  await new Promise((r) => setTimeout(r, 500));
  const expanded = await page.$eval('#cgpt-nav-panel', (el) => !el.classList.contains('collapsed'));
  console.log(`  ${expanded ? '✅' : '❌'} 展开恢复`);

  // === Markdown 导出 ===
  console.log('\n--- Markdown 导出 ---');
  const downloadDir = path.join(__dirname, 'test-downloads');
  fs.mkdirSync(downloadDir, { recursive: true });
  fs.readdirSync(downloadDir).forEach((f) => fs.unlinkSync(path.join(downloadDir, f)));

  const client = await page.createCDPSession();
  await client.send('Page.setDownloadBehavior', { behavior: 'allow', downloadPath: downloadDir });
  await page.click('#cgpt-nav-export-btn');
  await new Promise((r) => setTimeout(r, 3000));

  const downloads = fs.readdirSync(downloadDir);
  console.log(`  ${downloads.length > 0 ? '✅' : '❌'} 文件: ${downloads.length > 0 ? downloads.join(', ') : '无'}`);

  if (downloads.length > 0) {
    const md = fs.readFileSync(path.join(downloadDir, downloads[0]), 'utf-8');
    const lines = md.split('\n');
    console.log(`  行数: ${lines.length}`);

    for (const [desc, pass] of [
      ['# 标题', lines.some((l) => /^# /.test(l))],
      ['## 二级标题', lines.some((l) => /^## /.test(l))],
      ['### 三级标题', lines.some((l) => /^### /.test(l))],
      ['#### 四级标题', lines.some((l) => /^#### /.test(l))],
      ['``` 代码块', lines.some((l) => /^```/.test(l))],
      ['** 加粗', md.includes('**')],
      ['--- 分隔线', lines.some((l) => l.trim() === '---')],
      ['User/Assistant', md.includes('User') && md.includes('Assistant')],
      ['| 表格', lines.some((l) => /^\|/.test(l))],
      ['- 无序列表', lines.some((l) => /^- /.test(l))],
      ['1. 有序列表', lines.some((l) => /^\d+\. /.test(l))],
      ['[]() 链接', md.includes('](')],
      ['` 行内代码', /`[^`]+`/.test(md)],
      ['* 斜体', /(?<!\*)\*[^*]+\*(?!\*)/.test(md)],
