  await new Promise((r) => setTimeout(r, 1500));
  const after = await page.$$eval('.cgpt-nav-item', (els) => els.length);
  console.log(`  ${after > before ? '✅' : '❌'} 自动刷新: ${before} → ${after}`);

  // 截图
  await page.screenshot({ path: path.join(__dirname, 'test-screenshot.png') });
  console.log(`\n截图: test-screenshot.png`);

  if (logs.length > 0) {
    console.log('\n--- 控制台 ---');
    logs.slice(0, 10).forEach((l) => console.log(`  ${l}`));
  }

  console.log('\n=== 验证完成 ===');
  server.close();
  await browser.close();
}

test().catch((err) => {
  console.error('测试失败:', err.message);
