/**
 * 使用 Puppeteer 在真实 ChatGPT 分享页面验证插件
 */
import { createRequire } from 'module';
import path from 'path';
import fs from 'fs';
import { fileURLToPath } from 'url';

const require = createRequire('/Users/leon/Library/pnpm/global/5/node_modules/puppeteer/');
const puppeteer = require('puppeteer');

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT_DIR = path.resolve(__dirname, '..');
const CHROME_PATH = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const LIVE_URL = 'https://chatgpt.com/share/69d20f2c-5898-8327-8113-9b152b15f133';

async function test() {
  console.log('=== ChatGPT Navigator 插件 — 真实页面验证 ===\n');

  const browser = await puppeteer.launch({
    headless: false,
    executablePath: CHROME_PATH,
    args: [
      `--disable-extensions-except=${ROOT_DIR}`,
      `--load-extension=${ROOT_DIR}`,
      '--no-first-run',
      '--disable-default-apps',
    ],
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900 });

  const logs = [];
  page.on('console', (msg) => logs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => logs.push(`[ERROR] ${err.message}`));

  // 导航到真实分享页
  console.log(`1. 导航到 ${LIVE_URL}`);
  await page.goto(LIVE_URL, { waitUntil: 'domcontentloaded', timeout: 60000 });

  // 多轮等待，探测内容加载
  let contentLoaded = false;
  for (let i = 1; i <= 8; i++) {
    console.log(`   等待内容加载... (${i * 5}s)`);
    await new Promise((r) => setTimeout(r, 5000));

    const probe = await page.evaluate(() => {
      const msgCount = document.querySelectorAll('[data-message-author-role]').length;
      const articleCount = document.querySelectorAll('article').length;
      const markdownCount = document.querySelectorAll('.markdown, .prose').length;
      const textNodes = document.querySelectorAll('.whitespace-pre-wrap').length;
      // 检查页面是否有实际会话文本内容
      const bodyText = document.body.innerText.slice(0, 200);
      return { msgCount, articleCount, markdownCount, textNodes, bodyText };
    });
    console.log(`   messages=${probe.msgCount} articles=${probe.articleCount} markdown=${probe.markdownCount} textNodes=${probe.textNodes}`);

    if (probe.msgCount > 0 || probe.articleCount > 0 || probe.markdownCount > 0) {
      contentLoaded = true;
      break;
    }
  }

  // 不管是否加载到内容，都进行完整 DOM 探测
  console.log('\n--- 完整 DOM 探测 ---');

  // 探测所有 data-* 属性
  const dataAttrs = await page.evaluate(() => {
    const map = {};
    document.querySelectorAll('*').forEach((el) => {
      for (const attr of el.attributes) {
        if (attr.name.startsWith('data-')) {
          map[attr.name] = (map[attr.name] || 0) + 1;
        }
      }
    });
    return Object.entries(map).sort((a, b) => b[1] - a[1]).slice(0, 30);
  });
  console.log('  data-* 属性:');
  dataAttrs.forEach(([name, count]) => console.log(`    ${name}: ${count}`));

  // 探测所有 role 属性
  const roles = await page.evaluate(() => {
    const map = {};
    document.querySelectorAll('[role]').forEach((el) => {
      const r = el.getAttribute('role');
      map[r] = (map[r] || 0) + 1;
    });
    return Object.entries(map).sort((a, b) => b[1] - a[1]);
  });
  console.log('  role 属性:');
  roles.forEach(([name, count]) => console.log(`    ${name}: ${count}`));

  // 探测 class 中含 message/chat/turn/thread/conversation 的元素
  const classProbe = await page.evaluate(() => {
    const keywords = ['message', 'chat', 'turn', 'thread', 'conversation', 'markdown', 'prose', 'agent'];
    const results = {};
    for (const kw of keywords) {
      const els = document.querySelectorAll(`[class*="${kw}"]`);
      if (els.length > 0) {
        results[kw] = {
          count: els.length,
          samples: [...els].slice(0, 3).map((el) => ({
            tag: el.tagName.toLowerCase(),
            class: (typeof el.className === 'string' ? el.className : '').slice(0, 120),
            children: el.children.length,
            textLen: el.textContent?.length || 0,
          })),
        };
      }
    }
    return results;
  });
  console.log('  class 关键词探测:');
  for (const [kw, info] of Object.entries(classProbe)) {
    console.log(`    "${kw}": ${info.count} 个`);
    info.samples.forEach((s) => console.log(`      <${s.tag}> .${s.class.slice(0, 80)} (${s.children}ch, ${s.textLen}chars)`));
  }

  // 深度探测 main 结构
  const mainTree = await page.evaluate(() => {
    const main = document.querySelector('main') || document.querySelector('#__next') || document.body;
    const walk = (el, depth = 0) => {
      if (depth > 6 || !el?.tagName) return '';
      const tag = el.tagName.toLowerCase();
      const cls = typeof el.className === 'string' ? el.className.split(' ').filter(Boolean).slice(0, 4).join('.') : '';
      const id = el.id ? `#${el.id}` : '';
      const role = el.getAttribute('role') ? `[role=${el.getAttribute('role')}]` : '';
      const dRole = el.getAttribute('data-message-author-role') || '';
      const extra = dRole ? `[author=${dRole}]` : '';
      const textLen = el.textContent?.length || 0;
      let line = `${'  '.repeat(depth)}${tag}${id}${cls ? '.' + cls : ''}${role}${extra} (${el.children.length}ch, ${textLen}t)\n`;
      // Only expand children if reasonable
      if (el.children.length <= 30 && depth < 6) {
        for (const c of el.children) line += walk(c, depth + 1);
      }
      return line;
    };
    return walk(main).slice(0, 5000);
  });
  console.log('\n  DOM 树:');
  console.log(mainTree);

  // 检查 h1-h6
  const headings = await page.evaluate(() => {
    return [...document.querySelectorAll('h1,h2,h3,h4,h5,h6')].slice(0, 15).map((h) =>
      `${h.tagName} "${h.textContent.trim().slice(0, 60)}" (parent: ${h.parentElement?.className?.slice(0, 40)})`
    );
  });
  if (headings.length > 0) {
    console.log('  标题元素:');
    headings.forEach((h) => console.log(`    ${h}`));
  }

  // 检查插件面板
  console.log('\n--- 插件面板 ---');
  const panelEl = await page.$('#cgpt-nav-panel');
  console.log(`  ${panelEl ? '✅' : '❌'} 面板: ${!!panelEl}`);

  if (panelEl) {
    const navItems = await page.$$eval('.cgpt-nav-item', (els) =>
      els.map((e) => ({ type: e.dataset.type, level: e.dataset.level, text: e.textContent.slice(0, 60) }))
    );
    console.log(`  导航条目: ${navItems.length}`);
    navItems.slice(0, 20).forEach((item, i) =>
      console.log(`    [${i}] ${item.type}${item.level ? ' h' + item.level : ''}: ${item.text}`)
    );

    // 点击测试
    if (navItems.length > 1) {
      await page.click('.cgpt-nav-item:nth-child(2)');
      await new Promise((r) => setTimeout(r, 1500));
      const active = await page.$eval('.cgpt-nav-item.active', (el) => el.textContent.slice(0, 40)).catch(() => null);
      console.log(`  ${active ? '✅' : '❌'} 点击高亮: "${active}"`);
    }

    // 折叠
    await page.click('#cgpt-nav-toggle');
    await new Promise((r) => setTimeout(r, 500));
    const collapsed = await page.$eval('#cgpt-nav-panel', (el) => el.classList.contains('collapsed'));
    console.log(`  ${collapsed ? '✅' : '❌'} 折叠`);
    await page.click('#cgpt-nav-toggle');
    await new Promise((r) => setTimeout(r, 500));

    // 导出
    const downloadDir = path.join(__dirname, 'test-downloads');
    fs.mkdirSync(downloadDir, { recursive: true });
    fs.readdirSync(downloadDir).forEach((f) => fs.unlinkSync(path.join(downloadDir, f)));
    const client = await page.createCDPSession();
    await client.send('Page.setDownloadBehavior', { behavior: 'allow', downloadPath: downloadDir });
    await page.click('#cgpt-nav-export-btn');
    await new Promise((r) => setTimeout(r, 3000));
    const downloads = fs.readdirSync(downloadDir);
    console.log(`  ${downloads.length > 0 ? '✅' : '❌'} 导出文件: ${downloads.join(', ') || '无'}`);

    if (downloads.length > 0) {
      const md = fs.readFileSync(path.join(downloadDir, downloads[0]), 'utf-8');
      const lines = md.split('\n');
      console.log(`  行数: ${lines.length}`);
      // 检查代码块格式
      const codeBlockStarts = lines.filter((l) => /^```/.test(l));
      console.log(`  代码块围栏: ${codeBlockStarts.length} 个`);
      codeBlockStarts.forEach((l) => console.log(`    ${l}`));

      // 检查是否有裸露的语言标签（bug 标志）
      const langLeaks = lines.filter((l) => /^\s*(javascript|typescript|python|json|html|css|bash|sh)\s*$/i.test(l));
      console.log(`  ${langLeaks.length === 0 ? '✅' : '❌'} 语言标签泄漏: ${langLeaks.length}`);
      langLeaks.forEach((l) => console.log(`    泄漏: "${l}"`));

      // 内容预览
      console.log('\n  --- 导出预览 (前50行) ---');
      lines.slice(0, 50).forEach((l) => console.log(`  | ${l}`));
      if (lines.length > 50) console.log(`  | ... (共 ${lines.length} 行)`);

      // 格式检查
      for (const [desc, pass] of [
        ['代码块 ```', codeBlockStarts.length > 0],
        ['加粗 **', md.includes('**')],
        ['User/Assistant', md.includes('User') && md.includes('Assistant')],
      ]) {
        console.log(`  ${pass ? '✅' : '❌'} ${desc}`);
      }
    }
  } else {
    // 面板不存在，检查原因
    const urlInfo = await page.evaluate(() => ({ href: location.href, pathname: location.pathname }));
    console.log(`  URL: ${JSON.stringify(urlInfo)}`);
    console.log(`  isConversationPage 匹配: ${/^\/(c|share|g)\/[a-zA-Z0-9-]+/.test(urlInfo.pathname)}`);
  }

  // 截图
  const ssPath = path.join(__dirname, 'test-screenshot.png');
  await page.screenshot({ path: ssPath, fullPage: false });
  console.log(`\n截图: ${ssPath}`);

  if (logs.length > 0) {
    console.log('\n--- 控制台日志 (前15条) ---');
    logs.slice(0, 15).forEach((l) => console.log(`  ${l}`));
  }

  console.log('\n=== 验证完成 ===');
  await browser.close();
}

test().catch((err) => {
  console.error('测试失败:', err.message);
  process.exit(1);
});

