/**
 * 在真实 ChatGPT 页面验证插件 — 真实扩展加载
 */
import { createRequire } from 'module';
import path from 'path';
import fs from 'fs';
import { fileURLToPath } from 'url';

const require = createRequire('/Users/leon/Library/pnpm/global/5/node_modules/puppeteer/');
const puppeteer = require('puppeteer');

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT_DIR = path.resolve(__dirname, '..');
const CHROME_PATH = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const LIVE_URL = 'https://chatgpt.com/share/69d20f2c-5898-8327-8113-9b152b15f133';

// 复制插件到无中文字符的临时路径（避免 --load-extension 路径问题）
const TMP_EXT = '/tmp/cgpt-nav-ext';

function copyExtension() {
  fs.rmSync(TMP_EXT, { recursive: true, force: true });
  fs.mkdirSync(TMP_EXT, { recursive: true });
  for (const f of ['manifest.json', 'content.js', 'styles.css']) {
    fs.copyFileSync(path.join(ROOT_DIR, f), path.join(TMP_EXT, f));
  }
  console.log(`扩展已复制到 ${TMP_EXT}`);
}

async function test() {
  console.log('=== ChatGPT Navigator — 真实扩展 + 真实页面验证 ===\n');

  copyExtension();

  // 用独立 user-data-dir 避免冲突
  const userDataDir = '/tmp/cgpt-nav-chrome-profile';
  fs.rmSync(userDataDir, { recursive: true, force: true });

  const browser = await puppeteer.launch({
    headless: false,
    executablePath: CHROME_PATH,
    userDataDir,
    args: [
      `--disable-extensions-except=${TMP_EXT}`,
      `--load-extension=${TMP_EXT}`,
      '--no-first-run',
      '--disable-default-apps',
      '--no-default-browser-check',
    ],
  });

  // 先验证扩展是否加载
  const extPage = await browser.newPage();
  await extPage.goto('chrome://extensions/', { waitUntil: 'load' });
  await new Promise((r) => setTimeout(r, 2000));

  // 通过 chrome://extensions 的 shadow DOM 查看扩展列表
  const extInfo = await extPage.evaluate(() => {
    const mgr = document.querySelector('extensions-manager');
    if (!mgr?.shadowRoot) return { error: 'no extensions-manager' };
    const list = mgr.shadowRoot.querySelector('extensions-item-list');
    if (!list?.shadowRoot) return { error: 'no item-list' };
    const items = list.shadowRoot.querySelectorAll('extensions-item');
    return [...items].map((item) => {
      const name = item.shadowRoot?.querySelector('#name')?.textContent?.trim();
      const status = item.shadowRoot?.querySelector('#enable-toggle')?.getAttribute('checked');
      return { name, enabled: status !== null };
    });
  });
  console.log('扩展列表:', JSON.stringify(extInfo));
  await extPage.close();

  // 打开真实 ChatGPT 页面
  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900 });

  console.log(`\n导航到 ${LIVE_URL}`);
  await page.goto(LIVE_URL, { waitUntil: 'domcontentloaded', timeout: 60000 });

  // 等待内容 + content script 加载
  for (let i = 1; i <= 10; i++) {
    await new Promise((r) => setTimeout(r, 3000));
    const state = await page.evaluate(() => ({
      messages: document.querySelectorAll('[data-message-author-role]').length,
      panel: !!document.getElementById('cgpt-nav-panel'),
      navItems: document.querySelectorAll('.cgpt-nav-item').length,
    }));
    console.log(`  [${i * 3}s] messages=${state.messages} panel=${state.panel} navItems=${state.navItems}`);
    if (state.panel && state.navItems > 0) break;
  }

  // === 验证面板 ===
  console.log('\n--- 验证结果 ---');
  const panelExists = await page.$('#cgpt-nav-panel');
  console.log(`${panelExists ? '✅' : '❌'} 面板存在: ${!!panelExists}`);

  if (!panelExists) {
    console.log('\n  调试: 检查扩展 content script 是否注入...');
    // 检查 styles.css 是否被注入
    const cssInjected = await page.evaluate(() => {
      const sheets = [...document.styleSheets];
      return sheets.some((s) => {
        try { return [...s.cssRules].some((r) => r.selectorText?.includes('cgpt-nav')); }
        catch { return false; }
      });
    });
    console.log(`  CSS 注入: ${cssInjected}`);

    const ssPath = path.join(__dirname, 'test-screenshot.png');
    await page.screenshot({ path: ssPath });
    console.log(`  截图: ${ssPath}`);
    await browser.close();
    fs.rmSync(userDataDir, { recursive: true, force: true });
    process.exit(1);
  }

  // 面板尺寸
  const panelStyle = await page.$eval('#cgpt-nav-panel', (el) => ({
    w: el.offsetWidth, h: el.offsetHeight,
  }));
  console.log(`✅ 面板尺寸: ${panelStyle.w}x${panelStyle.h}`);

  // === 导航条目 ===
  const navItems = await page.$$eval('.cgpt-nav-item', (els) =>
    els.map((e) => ({ type: e.dataset.type, level: e.dataset.level, text: e.textContent.slice(0, 70) }))
  );
  const userItems = navItems.filter((i) => i.type === 'user').length;
  const headingItems = navItems.filter((i) => i.type === 'heading').length;
  console.log(`✅ 导航条目: ${navItems.length} (用户: ${userItems}, 标题: ${headingItems})`);
  navItems.slice(0, 25).forEach((item, i) =>
    console.log(`  [${String(i).padStart(2)}] ${(item.type + (item.level ? ' h' + item.level : '')).padEnd(12)} ${item.text}`)
  );
  if (navItems.length > 25) console.log(`  ... 共 ${navItems.length} 条`);

  // === 点击滚动 ===
  if (navItems.length > 2) {
    const idx = Math.min(5, navItems.length);
    await page.click(`.cgpt-nav-item:nth-child(${idx})`);
    await new Promise((r) => setTimeout(r, 1500));
    const active = await page.$eval('.cgpt-nav-item.active', (el) => el.textContent.slice(0, 50)).catch(() => null);
    console.log(`${active ? '✅' : '❌'} 点击导航 → active: "${active}"`);
  }

  // === 折叠/展开 ===
  await page.click('#cgpt-nav-toggle');
