// 复制插件到无中文字符的临时路径（避免 --load-extension 路径问题）
const TMP_EXT = '/tmp/cgpt-nav-ext';

function copyExtension() {
  fs.rmSync(TMP_EXT, { recursive: true, force: true });
  fs.mkdirSync(TMP_EXT, { recursive: true });
  for (const f of ['manifest.json', 'content.js', 'styles.css']) {
    fs.copyFileSync(path.join(ROOT_DIR, f), path.join(TMP_EXT, f));
  }
  console.log(`扩展已复制到 ${TMP_EXT}`);
}

