/**
 * Playwright 真实扩展 + 真实 ChatGPT 页面验证
 */
const { createRequire } = require('module');
const req = createRequire('/Users/leon/Library/pnpm/global/5/node_modules/playwright/');
const { chromium } = req('playwright');
const fs = require('fs');
const path = require('path');

const EXT_DIR = '/tmp/cgpt-nav-ext';
const LIVE_URL = 'https://chatgpt.com/share/69d20f2c-5898-8327-8113-9b152b15f133';

async function run() {
  console.log('=== ChatGPT Navigator — Playwright 真实扩展验证 ===\n');

  // 复制插件到无中文路径
  const rootDir = path.resolve(__dirname, '..');
  fs.rmSync(EXT_DIR, { recursive: true, force: true });
  fs.mkdirSync(EXT_DIR, { recursive: true });
  for (const f of ['manifest.json', 'content.js', 'styles.css']) {
    fs.copyFileSync(path.join(rootDir, f), path.join(EXT_DIR, f));
  }

  const userDataDir = '/tmp/cgpt-nav-pw-profile';
  fs.rmSync(userDataDir, { recursive: true, force: true });

  // Playwright 的 launchPersistentContext 原生支持扩展加载
  const context = await chromium.launchPersistentContext(userDataDir, {
    headless: false,
    channel: 'chrome',
    args: [
      '--disable-extensions-except=' + EXT_DIR,
      '--load-extension=' + EXT_DIR,
      '--no-first-run',
      '--no-default-browser-check',
    ],
  });

  // 1. 验证扩展是否已加载
  console.log('1. 验证扩展加载...');
  const extPage = await context.newPage();
  await extPage.goto('chrome://extensions/');
  await extPage.waitForTimeout(3000);
  await extPage.screenshot({ path: path.join(__dirname, 'test-ext-page.png') });
  await extPage.close();

  // 2. 导航到真实 ChatGPT 分享页
  console.log('2. 导航到 ChatGPT 分享页...');
  const page = await context.newPage();
  await page.setViewportSize({ width: 1400, height: 900 });
  await page.goto(LIVE_URL, { waitUntil: 'domcontentloaded', timeout: 60000 });

  // 等待内容和 content script
  for (let i = 1; i <= 10; i++) {
    await page.waitForTimeout(3000);
    const s = await page.evaluate(function () {
      return {
        msgs: document.querySelectorAll('[data-message-author-role]').length,
        panel: !!document.getElementById('cgpt-nav-panel'),
        items: document.querySelectorAll('.cgpt-nav-item').length,
      };
    });
    console.log('  [' + (i * 3) + 's] msgs=' + s.msgs + ' panel=' + s.panel + ' items=' + s.items);
    if (s.panel && s.items > 0) break;
  }

  // 3. 验证面板
  console.log('\n--- 验证结果 ---');
  const panelExists = await page.evaluate(function () {
    return !!document.getElementById('cgpt-nav-panel');
  });
  console.log((panelExists ? '✅' : '❌') + ' 面板存在: ' + panelExists);

  if (!panelExists) {
    // 调试信息
    const cssInjected = await page.evaluate(function () {
      var sheets = Array.from(document.styleSheets);
      return sheets.some(function (s) {
        try {
          return Array.from(s.cssRules).some(function (r) {
            return r.selectorText && r.selectorText.indexOf('cgpt-nav') >= 0;
          });
        } catch (e) { return false; }
      });
    });
    console.log('  CSS 注入: ' + cssInjected);
    console.log('  截图: test-screenshot.png');
    await page.screenshot({ path: path.join(__dirname, 'test-screenshot.png') });
    await context.close();
    fs.rmSync(userDataDir, { recursive: true, force: true });
    process.exit(1);
  }

  // 面板尺寸
  var ps = await page.evaluate(function () {
    var el = document.getElementById('cgpt-nav-panel');
    return { w: el.offsetWidth, h: el.offsetHeight };
  });
  console.log('✅ 面板尺寸: ' + ps.w + 'x' + ps.h);

  // 4. 导航条目
  var navItems = await page.evaluate(function () {
    return Array.from(document.querySelectorAll('.cgpt-nav-item')).map(function (e) {
      return { type: e.dataset.type, level: e.dataset.level, text: e.textContent.slice(0, 70) };
    });
  });
  var userCount = navItems.filter(function (i) { return i.type === 'user'; }).length;
  var headingCount = navItems.filter(function (i) { return i.type === 'heading'; }).length;
  console.log('✅ 导航条目: ' + navItems.length + ' (用户: ' + userCount + ', 标题: ' + headingCount + ')');
  navItems.slice(0, 25).forEach(function (item, i) {
    var label = item.type + (item.level ? ' h' + item.level : '');
    console.log('  [' + i + '] ' + label.padEnd(12) + item.text);
  });
  if (navItems.length > 25) console.log('  ... 共 ' + navItems.length + ' 条');

  // 5. 点击滚动
  if (navItems.length > 2) {
    await page.click('.cgpt-nav-item:nth-child(3)');
    await page.waitForTimeout(1500);
    var active = await page.evaluate(function () {
      var el = document.querySelector('.cgpt-nav-item.active');
      return el ? el.textContent.slice(0, 50) : null;
    });
    console.log((active ? '✅' : '❌') + ' 点击高亮: "' + active + '"');
  }

  // 6. 折叠/展开
  await page.click('#cgpt-nav-toggle');
  await page.waitForTimeout(500);
  var collapsed = await page.evaluate(function () {
    return document.getElementById('cgpt-nav-panel').classList.contains('collapsed');
  });
  console.log((collapsed ? '✅' : '❌') + ' 折叠');
  await page.click('#cgpt-nav-toggle');
  await page.waitForTimeout(500);

  // 7. Markdown 导出
  var dlDir = path.join(__dirname, 'test-downloads');
  fs.mkdirSync(dlDir, { recursive: true });
  fs.readdirSync(dlDir).forEach(function (f) { fs.unlinkSync(path.join(dlDir, f)); });

  var downloadPromise = page.waitForEvent('download', { timeout: 10000 }).catch(function () { return null; });
  await page.click('#cgpt-nav-export-btn');
  var download = await downloadPromise;

  if (download) {
    var dlPath = path.join(dlDir, download.suggestedFilename());
    await download.saveAs(dlPath);
    var md = fs.readFileSync(dlPath, 'utf-8');
    var lines = md.split('\n');
    console.log('✅ 导出: ' + download.suggestedFilename() + ' (' + lines.length + ' 行)');

    // 代码块围栏
    var fences = lines.filter(function (l) { return l.startsWith('```'); });
    console.log('  代码围栏: ' + fences.length + ' 个');
    fences.forEach(function (l) { console.log('    ' + l); });

    // 语言标签泄漏
    var langLeaks = lines.filter(function (l) {
      return /^\s*(javascript|typescript|python|json|html|css|bash|sh|plaintext)\s*$/i.test(l);
    });
    console.log('  ' + (langLeaks.length === 0 ? '✅' : '❌') + ' 语言标签泄漏: ' + langLeaks.length);
    langLeaks.forEach(function (l) { console.log('    泄漏: "' + l.trim() + '"'); });

    // 单行代码块检查
    var inBlock = false, blockLines = 0, singleLineBlocks = 0;
    for (var li = 0; li < lines.length; li++) {
      if (lines[li].startsWith('```')) {
        if (inBlock) {
          if (blockLines <= 1) singleLineBlocks++;
          inBlock = false;
          blockLines = 0;
        } else {
          inBlock = true;
