const LIVE_URL = 'https://chatgpt.com/share/69d20f2c-5898-8327-8113-9b152b15f133';

async function run() {
  const ud = '/tmp/cgpt-probe2-profile';
  fs.rmSync(ud, { recursive: true, force: true });

  const ctx = await chromium.launchPersistentContext(ud, {
    headless: false,
    args: [
      '--disable-extensions-except=' + ROOT_DIR,
      '--load-extension=' + ROOT_DIR,
      '--no-first-run',
      '--no-default-browser-check',
    ],
  });

  var page = await ctx.newPage();
  await page.setViewportSize({ width: 1400, height: 900 });
  await page.goto(LIVE_URL, { waitUntil: 'domcontentloaded', timeout: 60000 });

  for (var i = 1; i <= 10; i++) {
    await page.waitForTimeout(3000);
    var msgs = await page.evaluate(function () {
      return document.querySelectorAll('[data-message-author-role]').length;
    });
    console.log('[' + (i * 3) + 's] msgs=' + msgs);
    if (msgs > 5) break;
  }

  var result = await page.evaluate(function () {
    var pre = document.querySelector('pre');
    if (!pre) return { error: 'no pre found' };

    // Find all text nodes and their depths
    var textNodes = [];
    function walkText(node, depth) {
      if (node.nodeType === 3) { // TEXT_NODE
        var text = node.textContent;
        if (text.trim()) {
          var path = [];
          var n = node.parentElement;
          for (var i = 0; i < 15 && n && n !== pre; i++) {
            path.unshift(n.tagName + (n.className ? '.' + n.className.split(' ').slice(0, 2).join('.') : ''));
            n = n.parentElement;
          }
          textNodes.push({
            text: text.substring(0, 200),
            depth: depth,
            path: path.join(' > '),
          });
        }
      }
      for (var c = node.firstChild; c; c = c.nextSibling) {
        walkText(c, depth + 1);
      }
    }
    walkText(pre, 0);

    // Find elements with specific roles or labels
    var buttons = pre.querySelectorAll('button');
    var buttonInfo = Array.from(buttons).map(function(b) {
      return { text: b.textContent.trim().substring(0, 50), className: (b.className || '').substring(0, 80) };
    });

    // Find spans that might contain language labels
    var spans = pre.querySelectorAll('span');
    var spanInfo = Array.from(spans).slice(0, 20).map(function(s) {
      return {
        text: s.textContent.substring(0, 50),
        className: (s.className || '').substring(0, 80),
        childCount: s.children.length,
      };
    });

    // Find code elements anywhere inside
    var codes = pre.querySelectorAll('code');
    var codeInfo = Array.from(codes).map(function(c) {
      return {
        className: (c.className || '').substring(0, 80),
        textStart: c.textContent.substring(0, 200),
        parentTag: c.parentElement ? c.parentElement.tagName : 'none',
      };
    });

    // Check for specific patterns - look for the actual code content
    // The code might be in spans with specific hljs or syntax classes
    var hljs = pre.querySelectorAll('[class*="hljs"]');
    var hljsInfo = Array.from(hljs).slice(0, 5).map(function(el) {
      return {
        tag: el.tagName,
        className: (el.className || '').substring(0, 100),
        textStart: el.textContent.substring(0, 100),
        childCount: el.children.length,
      };
    });

    return {
      preTextFull: pre.textContent.substring(0, 500),
      textNodeCount: textNodes.length,
      textNodes: textNodes.slice(0, 30),
      buttons: buttonInfo,
      spans: spanInfo.slice(0, 15),
      codes: codeInfo,
      hljs: hljsInfo,
    };
  });

  console.log('\n=== DEEP PRE PROBE ===');
  console.log('preTextFull:', JSON.stringify(result.preTextFull));
  console.log('\nText nodes (' + result.textNodeCount + '):');
  result.textNodes.forEach(function(t, i) {
    console.log('  [' + i + '] depth=' + t.depth + ' path: ' + t.path);
    console.log('       text:', JSON.stringify(t.text.substring(0, 100)));
  });
  console.log('\nButtons:', JSON.stringify(result.buttons, null, 2));
  console.log('\nSpans:', JSON.stringify(result.spans, null, 2));
  console.log('\nCode elements:', JSON.stringify(result.codes, null, 2));
  console.log('\nHLJS elements:', JSON.stringify(result.hljs, null, 2));

  await ctx.close();
  fs.rmSync(ud, { recursive: true, force: true });
}

run().catch(function (err) { console.error('Failed:', err.message); process.exit(1); });

