    var info = {
      tagName: cm.tagName,
      className: cm.className,
      role: cm.getAttribute('role'),
      childCount: cm.children.length,
      childNodeCount: cm.childNodes.length,
      children: [],
    };

    for (var i = 0; i < Math.min(cm.children.length, 20); i++) {
      var child = cm.children[i];
      info.children.push({
        tag: child.tagName,
        className: (child.className || '').substring(0, 80),
        text: child.textContent,
        innerHTML: child.innerHTML.substring(0, 200),
        childCount: child.children.length,
      });
    }

    // Also try: what does textContent of cm-content look like?
    info.fullText = cm.textContent.substring(0, 500);

    // Try innerText which respects line breaks
    info.innerText = cm.innerText.substring(0, 500);

    return info;
  });

  console.log('\n=== CM-CONTENT STRUCTURE ===');
  console.log('tag:', result.tagName, 'class:', result.className);
  console.log('role:', result.role);
  console.log('children:', result.childCount, 'childNodes:', result.childNodeCount);
  console.log('\nChildren:');
  result.children.forEach(function (c, i) {
    console.log('  [' + i + '] <' + c.tag + '> class="' + c.className + '" children=' + c.childCount);
    console.log('       text:', JSON.stringify(c.text));
    console.log('       html:', c.innerHTML.substring(0, 150));
  });
  console.log('\ntextContent:', JSON.stringify(result.fullText));
  console.log('\ninnerText:', JSON.stringify(result.innerText));

  await ctx.close();
  fs.rmSync(ud, { recursive: true, force: true });
}

run().catch(function (err) { console.error('Failed:', err.message); process.exit(1); });

